window.ScripturaLexicons.BDAG_PART_0157 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epheuretes-bdag\" data-source=\"BDAG\" data-search=\"ἐφευρετής, οῦ, ὁ epheuretḗs substantivo masculino inventor; idealizador; urdidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφευρετής, οῦ, ὁ</td><td>substantivo masculino</td><td>inventor; idealizador; urdidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephebos-bdag\" data-source=\"BDAG\" data-search=\"Ἔφηβος, ου, ὁ Éphēbos nome próprio masculino Éfebo; Ephebus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἔφηβος, ου, ὁ</td><td>nome próprio masculino</td><td>Éfebo; Ephebus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephedomai-bdag\" data-source=\"BDAG\" data-search=\"ἐφήδομαι ephḗdomai verbo depoente comprazer-se; ter prazer, sobretudo no mal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφήδομαι</td><td>verbo depoente</td><td>comprazer-se; ter prazer, sobretudo no mal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephemeria-bdag\" data-source=\"BDAG\" data-search=\"ἐφημερία, ας, ἡ ephēmería substantivo feminino turno; classe sacerdotal; divisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφημερία, ας, ἡ</td><td>substantivo feminino</td><td>turno; classe sacerdotal; divisão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephemeros-bdag\" data-source=\"BDAG\" data-search=\"ἐφήμερος, ον ephḗmeros adjetivo de um dia; diário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφήμερος, ον</td><td>adjetivo</td><td>de um dia; diário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephikneomai-bdag\" data-source=\"BDAG\" data-search=\"ἐφικνέομαι ephiknéomai verbo depoente chegar a; alcançar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφικνέομαι</td><td>verbo depoente</td><td>chegar a; alcançar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephippos-bdag\" data-source=\"BDAG\" data-search=\"ἔφιππος, ον éphippos adjetivo montado; a cavalo; cavaleiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔφιππος, ον</td><td>adjetivo</td><td>montado; a cavalo; cavaleiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephistemi-bdag\" data-source=\"BDAG\" data-search=\"ἐφίστημι ephístēmi verbo pôr-se ao lado; sobrevir; atacar; estar presente; incumbir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφίστημι</td><td>verbo</td><td>pôr-se ao lado; sobrevir; atacar; estar presente; incumbir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephodion-bdag\" data-source=\"BDAG\" data-search=\"ἐφόδιον, ου, τό ephódion substantivo neutro provisão para viagem; viático BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφόδιον, ου, τό</td><td>substantivo neutro</td><td>provisão para viagem; viático</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephorao-bdag\" data-source=\"BDAG\" data-search=\"ἐφοράω ephoráō verbo olhar atentamente; contemplar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφοράω</td><td>verbo</td><td>olhar atentamente; contemplar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephraim-bdag\" data-source=\"BDAG\" data-search=\"Ἐφραίμ, ὁ Ephraím nome próprio masculino e topônimo Efraim; filho de José; cidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐφραίμ, ὁ</td><td>nome próprio masculino e topônimo</td><td>Efraim; filho de José; cidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephphatha-bdag\" data-source=\"BDAG\" data-search=\"εφφαθα ephphathá expressão aramaica transliterada abre-te BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εφφαθα</td><td>expressão aramaica transliterada</td><td>abre-te</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echthes-bdag\" data-source=\"BDAG\" data-search=\"ἐχθές echthés advérbio temporal ontem; no passado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐχθές</td><td>advérbio temporal</td><td>ontem; no passado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echthra-bdag\" data-source=\"BDAG\" data-search=\"ἔχθρα, ας, ἡ échthra substantivo feminino inimizade; hostilidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔχθρα, ας, ἡ</td><td>substantivo feminino</td><td>inimizade; hostilidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echthros-bdag\" data-source=\"BDAG\" data-search=\"ἐχθρός, ά, όν echthrós adjetivo e substantivo odiado; hostil; inimigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐχθρός, ά, όν</td><td>adjetivo e substantivo</td><td>odiado; hostil; inimigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echidna-bdag\" data-source=\"BDAG\" data-search=\"ἔχιδνα, ης, ἡ échidna substantivo feminino serpente; víbora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔχιδνα, ης, ἡ</td><td>substantivo feminino</td><td>serpente; víbora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-echo-bdag\" data-source=\"BDAG\" data-search=\"ἔχω échō verbo ter; possuir; manter; experimentar; poder; estar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔχω</td><td>verbo</td><td>ter; possuir; manter; experimentar; poder; estar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heos-bdag\" data-source=\"BDAG\" data-search=\"ἕως héōs conjunção e preposição até; até que; enquanto; até o limite BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕως</td><td>conjunção e preposição</td><td>até; até que; enquanto; até o limite</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heosphoros-bdag\" data-source=\"BDAG\" data-search=\"ἑωσφόρος, ου, ὁ heōsphóros substantivo masculino estrela da manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑωσφόρος, ου, ὁ</td><td>substantivo masculino</td><td>estrela da manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-stigma-bdag\" data-source=\"BDAG\" data-search=\"Ϛ stígma; vaû letra e numeral grego estigma; vau; numeral seis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ϛ</td><td>letra e numeral grego</td><td>estigma; vau; numeral seis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-epheuretes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφευρετής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epheuretḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφευρετής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>. Ver <span class=\"greek\">εὑρίσκω</span>. A transcrição da fonte abrevia a remissão com <span class=\"greek\">ς</span>. [equivalente a «ver»]. Anacreontea 38, 3, edição Preisendanz; Porfírio, <em>Against the Christians</em> [ABA 1916], 15, 1; Etymologicum Magnum, p. 435, 28. <strong>Pessoa que concebe estratégias ou expedientes para realizar algo: inventor; idealizador; urdidor.</strong> <span class=\"greek\">ἐφευρεταὶ</span> <span class=\"greek\">κακῶν</span>, «inventores [ou maquinadores] de males», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:30</a>. Cf. Teofilacto Simocata, Ep. 29, p. 772 H. <span class=\"greek\">κακῶν</span> <span class=\"greek\">ἐφευρετικόν</span>, «engenhoso para o mal»; Fílon, In Flacc. 20 <span class=\"greek\">κακῶν</span> <span class=\"greek\">εὑρεταί</span>, «inventores de males», e 73; 2Mc 7:31; Virgílio, <em>Eneida</em> 2, 164, <em>scelerum inventor Ulixes</em>, «Ulisses, inventor de crimes»; Tácito, <em>Annales</em> 4, 11, <em>Seianus facinorum omnium repertor</em>, «Sejano, urdidor de toda espécie de crimes». Bibliografia: DELG, s.v. <span class=\"greek\">εὑρίσκω</span>; M-M.</p></section></article>\n<article id=\"entry-ephebos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἔφηβος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Éphēbos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἔφηβος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>. Ver, por exemplo, <em>Inscriptiones Hispaniae Latinae</em>, ed. Hübner (1869), n.º 4970, 172; <em>Inscriptiones Parietariae Pompeianae</em>, ed. K. Zangemeister (1871), n.º 1478; SEG XXVI 184; XXXIX 1205 (nome próprio ou <span class=\"greek\">ἔφηβο</span> como categoria etária?). <strong>Éfebo (Ephebus)</strong>, cristão romano cujo prenome era Cláudio, 1Cl 65:1.</p></section></article>\n<article id=\"entry-ephedomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφήδομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephḗdomai⟧</span><span class=\"separator\">·</span><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφήδομαι</span>. Ver <span class=\"greek\">ἥδομαι</span>. Xenofonte e outros. <strong>Sentir prazer; comprazer-se</strong>, predominantemente no mau sentido de «alegrar-se com a desgraça alheia» ou «sentir prazer em coisas más» (Dião Crisóstomo 3, 103; 10 [11], 64; Élio Aristides 36, p. 690 D.; Josefo, C. Ap. 2, 5). <strong>Com dativo <span class=\"greek\">τινί</span></strong>, «comprazer-se em alguma coisa» (Xenofonte, Hell. 4, 5, 18; Josefo, Ant. 16, 127): <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁμαρτήμασιν</span>, «nos pecados», Dg 9:1.</p></section></article>\n<article id=\"entry-ephemeria-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφημερία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephēmería⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφημερία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver <span class=\"greek\">ἡμέρα</span> e o verbete seguinte. SEG VII 29 [séc. I a.C.]. <strong>Classe de sacerdotes que desempenha diariamente seus deveres por período fixo no templo de Jerusalém: turno; classe; divisão sacerdotal</strong> (LXX; Josefo, Ant. 12, 265). Eram 24 divisões, cada qual responsável pelos deveres do templo durante uma semana (1Cr 23:6; 28:13 e outros). Schürer II 245–50; Billerbeck II 55ss. A <span class=\"greek\">ἐ</span>. <span class=\"greek\">Ἀβιά</span>, «classe de Abias», em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:5</a>, era a oitava divisão. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τάξει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐφημερίας</span> <span class=\"greek\">αὐτοῦ</span>, «segundo a ordem de seu turno», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:8</a>. Bibliografia: DELG, s.v. <span class=\"greek\">ἦμαρ</span>; M-M; TW.</p></section></article>\n<article id=\"entry-ephemeros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφήμερος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephḗmeros⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφήμερος</span>, <span class=\"greek\">ον</span>. Ver o verbete precedente. Píndaro, Tucídides e outros; Fílon; ApcrEzk P 1, recto 9. <strong>Destinado ao dia; diário; de cada dia.</strong> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τροφή</span>, «o alimento de cada dia» (Diodoro Sículo 3, 32, 3; Dionísio de Halicarnasso 8, 41, 5; Élio Aristides 28, 139 K. = 49, p. 537 D.; Estobeu 1, 1, 13 [I, p. 27 W.]; Vécio Valente p. 62, 17 <span class=\"greek\">ἐνδεεῖς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τροφῆς</span>, «necessitados do alimento diário»; PCairZen 4, 647, 20 [séc. III a.C.]; PSI 685, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:15</a>. Bibliografia: H. Fränkel, TAPA 77 (1946), 131–45; M-M; Sv.</p></section></article>\n<article id=\"entry-ephikneomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφικνέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephiknéomai⟧</span><span class=\"separator\">·</span><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφικνέομαι</span>. Segundo aoristo <span class=\"greek\">ἐφικόμην</span>. Ver <span class=\"greek\">ἱκνέομαι</span>, «vir; chegar». Homero e outros; IPriene 105, 47; Sir 43:27, códice C; SibOr 11, 215; Justino, D. 4, 2 <span class=\"greek\">ἐφικτόν</span>, «alcançável». <strong>Chegar a algo ou alguém; alcançar.</strong> Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, «até alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:14</a>; com <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τινός</span>, «até alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:13</a>. Bibliografia: DELG, s.v. <span class=\"greek\">ἵκω</span>.</p></section></article>\n<article id=\"entry-ephippos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔφιππος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éphippos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔφιππος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">ἵππος</span>. Sófocles e outros; PLond 1912, 44; 4Mc 11:8 <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">λευκῇ</span> <span class=\"greek\">ἐσθῆτι</span>, «montado, com vestes brancas»; 12:35 <span class=\"greek\">τὶς</span> … <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἀνήρ</span>, «certo homem montado»; 4Mc 4:10 <span class=\"greek\">ἔ</span>. … <span class=\"greek\">ἄγγελοι</span>, «anjos montados»; papiros. <strong>Que está sobre um cavalo: montado; a cavalo.</strong> Substantivado, «cavaleiro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19:14</a>, variante textual.</p></section></article>\n<article id=\"entry-ephistemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφίστημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephístēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφίστημι</span>. Ver <span class=\"greek\">ἵστημι</span>. Homero e posteriores; inscrições, papiros, LXX; TestJob 17:2; EpArist; Josefo; Justino (com a acepção «prestar atenção», D. 28, 1); Atenágoras. <strong>Paradigma:</strong> futuro <span class=\"greek\">ἐπιστήσω</span>; primeiro aoristo <span class=\"greek\">ἐπέστησα</span> na LXX; segundo aoristo <span class=\"greek\">ἐπέστην</span>, imperativo <span class=\"greek\">ἐπίστηθι</span>, particípio <span class=\"greek\">ἐπιστάς</span>; perfeito <span class=\"greek\">ἐφέστηκα</span> na LXX, particípio <span class=\"greek\">ἐφεστώς</span>; mais-que-perfeito, terceira pessoa do singular <span class=\"greek\">ἐφειστήκει</span> na LXX; médio, indicativo terceira pessoa do singular <span class=\"greek\">ἐπίσταται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:3</a>, variante textual (sobre a forma, W-S §5, 10c); primeiro aoristo passivo <span class=\"greek\">ἐπεστάθην</span>, 1Cl 12:4; Hv 3, 1, 6. Esse aoristo passivo pode ter valor médio (Eurípides, Iph. T. 1375 e outros). A voz média, como o segundo aoristo, perfeito e mais-que-perfeito ativos, normalmente é <strong>intransitiva</strong>. Só este valor intransitivo aparece na literatura aqui abrangida.</p><p class=\"entry-text\">① <strong>Colocar-se ou estar de pé junto a um lugar: aproximar-se; pôr-se ao lado; comparecer</strong>, para seres vivos, frequentemente com noção de súbita aparição. <strong>Presente e aoristo com dativo pessoal:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:9</a>; 24:4 (anjos; cf. Diodoro Sículo 1, 25, 5, Ísis em sonho; Luciano, Dial. Deor. 17, 1, Hefesto; SIG 1168, 37 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπιστάς</span>; TestSol 1:8 <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὥρᾳ</span> <span class=\"greek\">ἐπιστῇ</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span>; Josefo, Ant. 3, 188; quanto a figura onírica, Heródoto 5, 56); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:1</a>; 12:7, códice D; 23:11. <span class=\"greek\">ἐπεστάθη</span> <span class=\"greek\">μοι</span>, «aproximou-se de mim», Hv 3, 1, 6. <strong>Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span></strong>, «chegar junto de alguma coisa» (Sir 41:24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:17</a>; 11:11. <strong>Com <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τινός</span></strong>, «pôr-se junto à cabeceira de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:39</a> (cf. 2Km 1:9). <span class=\"greek\">περιστερὰ</span> … <span class=\"greek\">ἐπεστάθη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰωσήφ</span>, «uma pomba pousou na cabeça de José», GJs 9:1 (variante <span class=\"greek\">ἐπετάσθη</span>). <strong>Uso absoluto</strong> (EpArist 177), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:38</a>; 10:40; 20:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:12</a>; 12:7; 22:13; 23:27; 1Cl 12:4; MPol 6:1; GJs 4:1, variante; AcPl Ha 4, 8. <strong>Perfeito: estar ao lado; estar presente</strong>, <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἤμην</span> <span class=\"greek\">ἐφεστώς</span>, «eu mesmo estava ali presente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:20</a> (cf. Josefo, Vi. 294).</p><p class=\"entry-text\">② <strong>Acontecer, especialmente de calamidades que acometem alguém de súbito: sobrevir; atingir; abater-se</strong> (Sófocles, Oed. R. 777; Tucídides 3, 82, 2; LXX). Com dativo de pessoa (Cornuto 10, p. 11, 17; Wsd 6:8; 19:1): <span class=\"greek\">αἰφνίδιος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐφίσταται</span> <span class=\"greek\">ὄλεθρος</span>, «uma destruição repentina lhes sobrevém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:3</a>. <strong>Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span></strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:34</a>. Bibliografia: D. Daube, <em>The Sudden in the Scriptures</em> (1964), 36.</p><p class=\"entry-text\">③ <strong>Aproximar-se com intenção de prejudicar: atacar.</strong> Com dativo de coisa <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">Ἰ</span>., «a casa de Jasom», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:5</a>.</p><p class=\"entry-text\">④ <strong>Estar presente para iniciar alguma coisa: começar; sobrevir.</strong> Perfeito: <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑετὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐφεστῶτα</span>, «porque havia começado a chover», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:2</a> (Políbio 18, 20, 7 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐφεστῶτα</span> <span class=\"greek\">ζόφον</span>, «por causa da escuridão que sobreveio»). Entretanto, também pode significar «porque ameaçava chover» (ver ⑥).</p><p class=\"entry-text\">⑤ <strong>Estar pronto a executar uma incumbência: manter-se atento; perseverar</strong> (Eurípides, Andr. 547; Demóstenes 18, 60). <span class=\"greek\">ἐπίστηθι</span>, «permanece firme; esteja preparado; persiste», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:2</a>.</p><p class=\"entry-text\">⑥ <strong>Estar diante de alguém como acontecimento prestes a suceder: estar iminente</strong>, no perfeito (Ilíada 12, 326; Demóstenes 18, 176; Josefo, Ant. 13, 241; Vi. 137 e outros). <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναλύσεώς</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐφέστηκεν</span>, «o momento de minha partida está iminente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:6</a>. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:2</a>, ver ④.</p><p class=\"entry-text\">⑦ <strong>Estar colocado sobre algo como dirigente ou supervisor: estar encarregado; dirigir</strong>, perfeito (Eurípides, Aristófanes e outros; Jdt 8:10; 12:11; Sinésio, Ep. 140, p. 276b <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐφεστὼς</span> <span class=\"greek\">θεός</span>; Justino, D. 36, 6; Atenágoras 12, 1; 31, 2). <strong>Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>:</strong> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἱκοδομὴν</span> <span class=\"greek\">ἐφεστῶτες</span>, «os homens encarregados da construção», Hs 9, 6, 2. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-ephodion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφόδιον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephódion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφόδιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>. Ver <span class=\"greek\">ὁδός</span>. <strong>Provisões ou dinheiro destinados a uma viagem: viático; provisões de jornada</strong>, singular e plural em Aristófanes, Heródoto e outros; inscrições e papiros; Dt 15:14; Josefo, Vi. 224 e outros. <strong>Figuradamente</strong>, as provisões que Cristo concede a seus seguidores para a jornada da vida, 1Cl 2:1 (cf. Menandro, Fgm. 407, 2 Kö. <span class=\"greek\">ἐ</span>. <span class=\"greek\">βίῳ</span>, «viático para a vida»; Epicteto 3, 21, 9 <span class=\"greek\">ἔχοντάς</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">βίον</span>, «possuindo algo como provisões para a vida»; Plutarco, Mor. 160b; Sexto 551; Fílon, Rer. Div. Her. 273; Josefo, Bell. 1, 463; 6, 80). Bibliografia: DELG, s.v. <span class=\"greek\">ὁδό</span> [grafia abreviada da fonte; remissão a <span class=\"greek\">ὁδός</span>].</p></section></article>\n<article id=\"entry-ephorao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφοράω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephoráō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφοράω</span>. Futuro <span class=\"greek\">ἐπόψομαι</span>, LXX. Ver <span class=\"greek\">ὁράω</span>. Homero e posteriores; inscrições, papiros, LXX; Fílon, Aet. M. 83; Josefo, Bell. 1, 630; SibOr, Fgm. 3, 42; Justino, D. 127, 2. <strong>Olhar atentamente para algo; contemplar</strong>, com acusativo <span class=\"greek\">τὶ</span>, «algo», ApcPt 10:25. Ver também <span class=\"greek\">ἐπεῖδον</span>. Bibliografia: DELG, s.v. <span class=\"greek\">ὁράω</span>; TW.</p></section></article>\n<article id=\"entry-ephraim-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐφραίμ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Ephraím⟧</span><span class=\"separator\">·</span><span>nome próprio masculino e topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἐφραίμ</span>, <span class=\"greek\">ὁ</span>. Indeclinável; variante -<span class=\"greek\">άιμ</span>, em Bovon, N.25. Hebraico אֶפְרַיִם. LXX; JosAs 21:8; Fílon. Josefo apresenta diversas transliterações gregas (ver índice de sua obra). <strong>Efraim.</strong></p><p class=\"entry-text\">① <strong>Filho de José</strong>, abençoado por Jacó em lugar do irmão mais velho, Manassés (Gn 48:14, 17ss.; Demétrio, 722 Fgm. 1, 12), B 13:5.</p><p class=\"entry-text\">② <strong>Nome de uma cidade perto do deserto</strong>, para onde Jesus se retirou brevemente, segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.54\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:54</a>, ao aproximar-se do fim de sua vida. Sobre a localização segundo tradições antigas e interpretações modernas, ver os comentários ao versículo. O códice D apresenta <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χώραν</span> <span class=\"greek\">Σαμφουριν</span> (= Sepphoris) <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐρήμου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἐφραὶμ</span> <span class=\"greek\">λεγομένην</span> <span class=\"greek\">πόλιν</span>, «para a região de Samfurim (= Séforis), junto ao deserto, para uma cidade chamada Efraim». Bibliografia: T. Zahn, NKZ 19 (1908), 31–39; S. Case, «Jesus and Sepphoris», JBL 45 (1926), 14–22; BHHW 1, 420s.</p></section></article>\n<article id=\"entry-ephphatha-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εφφαθα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephphathá⟧</span><span class=\"separator\">·</span><span>expressão aramaica transliterada</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εφφαθα</span>. <strong>Palavra aramaica transcrita no texto grego</strong>, traduzida pelo próprio Evangelho como <span class=\"greek\">διανοίχθητι</span>, «abre-te», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:34</a>. Entende-se como contração da forma de <em>ethpeel</em> אֶתְפְּתַח; ver Wellhausen, comentário ao versículo. Bibliografia: G. Dalman, <em>Grammatik</em>, 2.ª ed., 278; I. Rabinowitz, ZNW 53 (1962), 229–38; J. Emerton, JTS 18 (1967), 427–31; contraponto em M. Black, <em>Festschrift B. Rigaux</em> (1970), 57–60; Hott, NovT 9 (1967).</p></section></article>\n<article id=\"entry-echthes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐχθές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦echthés⟧</span><span class=\"separator\">·</span><span>advérbio temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐχθές</span>. Advérbio. Sófocles e outros; também em prosa ática. Forma própria do grego koiné: PEleph 29, 6 [séc. III a.C.]; PSI 442, 21 [séc. III a.C.]; PLips 105, 1 [sécs. I/II d.C.]; PFay 108, 7 [séc. II d.C.]; LXX (Thackeray 97); Josefo, C. Ap. 2, 14 e outros. A forma <span class=\"greek\">χθές</span> aparece como variante em numerosos manuscritos do NT e sempre no <em>textus receptus</em>.</p><p class=\"entry-text\">① <strong>Dia imediatamente anterior ao atual: ontem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:35</a>, códice D; 7:28; 1Cl 4:10 (as duas últimas ocorrências citam Êx 2:14).</p><p class=\"entry-text\">② <strong>Tempo passado, em contraposição ao presente: ontem; outrora</strong> (Sófocles, Ant. 456 <span class=\"greek\">νῦν</span> <span class=\"greek\">κἀχθές</span>, «agora e ontem»; Élio Aristides 53, p. 623 D. <span class=\"greek\">χθές</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πρῴην</span>, «ontem e anteontem»; cf. Josefo, C. Ap. 2, 154). Com <span class=\"greek\">σήμερον</span>, «hoje; presente» (Sir 38:22; Himério, Ecl. 31, 1 W.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:8</a>. Ver <span class=\"greek\">χθές</span>. Bibliografia: DELG, s.v. <span class=\"greek\">χθέ</span>; M-M.</p></section></article>\n<article id=\"entry-echthra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔχθρα, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦échthra⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔχθρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete seguinte. Píndaro, Tucídides e outros; inscrições, papiros, LXX; ApcMos 25ss.; Justino, D. 1023, 3 [Gn 3:15]. <strong>Inimizade; hostilidade</strong>, Dg 5:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:14</a>, 16 (em oposição a <span class=\"greek\">φιλία</span>, «amizade», como Hipérides, Fgm. 209; Élio Aristides 38, p. 713 D.; SIG 826c, 10; PHib 170 [247 a.C.]). <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «inimizade contra Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:4</a>; também <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:7</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «viver em inimizade com alguém» (cf. 1Esd 5:49), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:12</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> também em Demétrio, 722 Fgm. 1, 1 Jac.; Luciano, Hermot. 85; Fílon, Spec. Leg. 1, 108; Josefo, Ant. 4, 106. <strong>Plural: sentimentos e ações hostis</strong> (Platão, sétima carta 337b; Fílon, Sacr. Abel. 96), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:20</a>. Bibliografia: B. 1132s.; DELG, s.v. <span class=\"greek\">ἔχθο</span>; M-M; TW.</p></section></article>\n<article id=\"entry-echthros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐχθρός, ά, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦echthrós⟧</span><span class=\"separator\">·</span><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐχθρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span>. Ver o verbete precedente. Homero e posteriores. Sentido geral: «hostil; inimigo».</p><p class=\"entry-text\">① <strong>Aquele que é alvo de hostilidade: odiado</strong>, emprego passivo (Homero; <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐ</span>., «odiado pelos deuses», desde Hesíodo, Theog. 766; Platão, Rep. 1, 23, 352b; Epicteto 3, 22, 91; Élio Aristides 28, 15 K. = 49, p. 495 D.; Alcífron 3, 12, 5; Ateneu 6, 225c; Aquiles Tácio 7, 6, 3; Xenofonte, Cyr. 5, 4, 35 <span class=\"greek\">καὶ</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώποις</span>, «odiado pelos deuses e pelos seres humanos»; Fílon, Spec. Leg. 3, 88 <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">θεῷ</span>, «todo aquele que é odiado por Deus»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:28</a>. Nessa passagem, o sentido passivo é bastante provável por contraste com <span class=\"greek\">ἀγαπητός</span>, «amado»; caso contrário, corresponde a ②ⓑ<span class=\"greek\">α</span>.</p><p class=\"entry-text\">② <strong>Aquele que nutre ódio: hostil; que odeia</strong>, emprego ativo (Píndaro, Heródoto e outros; LXX).</p><p class=\"entry-text\">ⓐ <strong>Como adjetivo</strong> (Xenofonte, An. 1, 3, 12, 20; PGM 36, 144; Sir 36:9; Josefo, Ant. 11, 27; Justino, D. 93, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">συνειδήσεσιν</span> <span class=\"greek\">ἐ</span>., «hostis em suas consciências»; Melitão, P. 16, 110 e outros). <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἄνθρωπος</span>, «homem hostil», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:28</a> (cf. Horapolo 2, 35). A posição de <span class=\"greek\">ἐ</span>. antes de <span class=\"greek\">ἄ</span>. (abreviação de <span class=\"greek\">ἄνθρωπος</span>) favorece a leitura adjetival, mas <span class=\"greek\">ἄ</span>. [= <span class=\"greek\">ἄνθρωπος</span>] pode simplesmente reforçar a indeterminação («algum inimigo», «qualquer inimigo»); nesse caso, caberia sob ⓑ (E. Klostermann, <em>Handbuch</em>, ad loc.).</p><p class=\"entry-text\">ⓑ <strong>Substantivado</strong>, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐ</span>., «o inimigo pessoal» (Hesíodo, Píndaro; PEdg 14 [= Sb 6720], 18 [257/256 a.C.]; LXX; En 103:12; Test12Patr; EpArist; Fílon; Josefo; SibOr 3, 727).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Uso absoluto:</strong> 2Cl 6:3. Inimigos de pessoas (PsSol 17:13; Ar. 15:5; Justino, A I, 68, 1 e outros; Melitão, P. 24, 175 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.74\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:74</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 3:15</a>; D 1:3b; B 16:4; 2Cl 13:4. <strong>Inimigos de Deus ou de Cristo</strong> (Justino, A I, 51, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:10</a>; 11:28 (mas ver ①); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:21</a>; 1Cl 36:6. <strong>A morte como último inimigo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:26</a>. <strong>O diabo como inimigo</strong> (TestSol 1:2 D; TestJob 47:10; TestDan 6:3s.; JosAs 12:8; GrBar 13:2; ApcMos 2:7 e outros; Melitão, P. 102, 783), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:39</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Com genitivo da pessoa contra quem se dirige a hostilidade.</strong> Acerca de pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:43</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:27</a>, 35 (cf. Ox 1224 Fgm. 2 recto I, 2; preceitos délficos em SIG 1286 I, 15–16 [séc. III a.C.] <span class=\"greek\">φίλοις</span> <span class=\"greek\">εὐνόει</span>, <span class=\"greek\">ἐχθροὺς</span> <span class=\"greek\">ἀμύνου</span>, «sê benevolente com os amigos, defende-te dos inimigos»; Sexto 213 <span class=\"greek\">εὔχου</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐχθροὺς</span> <span class=\"greek\">εὐεργετεῖν</span>, «ora para fazer bem aos inimigos»; Pítaco em Diógenes Laércio 1, 78 <span class=\"greek\">φίλον</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">κακῶς</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ἐχθρόν</span>, «não falar mal do amigo, nem sequer do inimigo»; Epicteto 3, 22, 54, princípio do cínico, <span class=\"greek\">δερόμενον</span> <span class=\"greek\">φιλεῖν</span> [<span class=\"greek\">δεῖ</span>] <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δέροντας</span> … <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀδελφόν</span>, «mesmo açoitado deve amar os que o açoitam como irmãos»; Vi. Aesop. G 110 P.; Hiérocles 7, p. 430 <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐχθρὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπουδαίῳ</span> … <span class=\"greek\">μισεῖ</span> <span class=\"greek\">οὐδένα</span> <span class=\"greek\">ἄνθρωπον</span> … <span class=\"greek\">φιλία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀνθρώπους</span>, «o virtuoso não tem inimigos; não odeia nenhum ser humano e é amistoso com todos»). Bibliografia pertinente: H. Haas, <em>Idee und Ideal der Feindesliebe in der ausserchristlichen Welt</em> (1927); M. Waldmann, <em>Die Feindesliebe in der antiken Welt und im Christentum</em> (1902); T. Birt, <em>Christliche Welt</em> 29 (1915), 475–83; F. Kattenbusch, StKr 89 (1916), 1–70; P. Fiebig, ibid. 91 (1918), 30–64, 305s.; J. Yates, <em>Theology</em> 44 (1942), 48–51; Betz, SM 301–13. Ocorrências: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:36</a>; 13:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:71</a>; 19:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:20</a> (Pv 25:21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:5</a>, 12; GJs 6:3. <strong>Deus ou Cristo como alvo da hostilidade:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a>; 10:13; B 12:10; 1Cl 36:5 (todas em relação a Sl 109:1). <span class=\"greek\">ἐχθρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «inimigo de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:4</a> (cf. Ésquilo, Prom. 120 <span class=\"greek\">ὁ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">ἐ</span>.; Justino, D. 93, 4 <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Com genitivo daquilo que é alvo da hostilidade</strong> (<span class=\"greek\">ἐ</span>. indica abreviadamente o adjetivo) (Demóstenes 45, 66; Fílon, Conf. Lingu. 48 <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">ἐ</span>., «inimigo da verdade»; Somn. 2, 90 <span class=\"greek\">λογισμοῦ</span>, «da razão»; Josefo, C. Ap. 2, 291 <span class=\"greek\">ἀδικίας</span>, «da injustiça»): <span class=\"greek\">ἐ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">δικαιοσύνης</span>, «inimigo de toda justiça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:10</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστοῦ</span>, «inimigo da cruz de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:18</a> (O. Linton, ConNeot 4 [1936], 9–21).</p><p class=\"entry-text\">Bibliografia: B. 1345; Schmidt, <em>Syn.</em> III 496–506; EDNT; M-M; TW.</p></section></article>\n<article id=\"entry-echidna-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔχιδνα, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦échidna⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔχιδνα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span>. Hesíodo; Heródoto e posteriores; Áquila, Is 59:5; TestAbr A; Justino, A I, 60, 2; Taciano 18, 2; Atenágoras 20, 3; empréstimo presente no rabínico. <strong>Serpente</strong>, geralmente entendida como venenosa; os textos aqui estudados não permitem identificar a espécie zoológica com certeza, mas é possível a <em>Vipera ammodytes</em>, frequentemente chamada víbora-de-areia (Diodoro Sículo 4, 38, 2; Conon [séc. I a.C./I d.C.], Fgm. 1, 8; Luciano, Alex. 10; Artemidoro 2, 13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:3</a>. A ilha de Malta atual não possui serpentes venenosas, mas Cefalênia, identificada por H. Warnecke como lugar do naufrágio de Paulo (<em>Romfahrt</em>, 145–56), abriga a espécie: ibid. 108–10; 152–54. <strong>Nota:</strong> a proposta geográfica de Warnecke não deve ser confundida com consenso histórico.</p><p class=\"entry-text\"><strong>Uso figurado aplicado a pessoas</strong> (Ésquilo, Choeph. 994; Eurípides, Ion 1262): <span class=\"greek\">γεννήματα</span> <span class=\"greek\">ἐχιδνῶν</span>, «raça de víboras» (cf. Teofilacto Simocata, Ep. 73 <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐχίδνης</span> <span class=\"greek\">κυήματα</span>, «os rebentos da víbora»; AcPlCor 2:38), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; 12:34; 23:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:7</a>. Bibliografia: O. Keller, <em>Die antike Tierwelt</em> II (1913), 284–557; N. Henkel, <em>Studien zum Physiologus im Mittelalter</em> (1976), 181–85, fontes antigas; Pauly-W. III A 1 (1927), 494–57; B. 194; M-M; TW.</p></section></article>\n<article id=\"entry-echo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦échō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔχω</span>. Homero e posteriores. Imperfeito <span class=\"greek\">εἶχον</span>; primeira pessoa do plural <span class=\"greek\">εἴχαμεν</span> e terceira pessoa do plural <span class=\"greek\">εἶχαν</span>, ambas variantes (Mlt-H. 194; B-D-F §82), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:8</a>; ou <span class=\"greek\">εἴχοσαν</span> (B-D-F §84, 2; Mlt-H. 194; Kühner-Bl. II, p. 55), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15:22</a>, 24. Segundo aoristo <span class=\"greek\">ἔσχον</span>; formas mistas do aoristo: <span class=\"greek\">ἔσχαν</span>, Hv 3, 5, 1; <span class=\"greek\">ἔσχοσαν</span>, 1Esd 6:5; 1Mc 10:15 (variantes <span class=\"greek\">ἔσχον</span>, <span class=\"greek\">εἴχον</span>). Perfeito <span class=\"greek\">ἔσχηκα</span>; mais-que-perfeito <span class=\"greek\">ἐσχήκειν</span>. <strong>Organização dos sentidos:</strong> ①–⑨, voz ativa transitiva; ⑩, ativa intransitiva; ⑪, voz média.</p><p class=\"entry-text\">① <strong>Possuir ou conter: ter; possuir; ser dono de algo.</strong></p><p class=\"entry-text\">ⓐ <strong>Possuir alguma coisa submetida ao próprio controle.</strong></p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Ser proprietário; ter em sua posse</strong> (especialmente TestJob 9ss.). <span class=\"greek\">κτήματα</span> <span class=\"greek\">πολλά</span>, «possuir muitos bens», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:22</a>. <span class=\"greek\">πρόβατα</span>, «ovelhas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:16</a>. <span class=\"greek\">θησαυρόν</span>, «tesouro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:21</a>b. <span class=\"greek\">βίον</span>, «recursos para viver», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:17</a>. <span class=\"greek\">δραχμὰς</span> <span class=\"greek\">δέκα</span>, «dez dracmas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:8</a>. <span class=\"greek\">πλοῖα</span>, «navios», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:19</a>. <span class=\"greek\">κληρονομίαν</span>, «herança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:5</a>. <span class=\"greek\">θυσιαστήριον</span>, «altar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:10</a>a. <span class=\"greek\">μέρος</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «ter parte em alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:6</a>. <strong>Uso geral:</strong> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἔ</span>., «não possuir coisa alguma» (SibOr 3, 244), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:10</a>. <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἔχεις</span>, «tudo quanto possuis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:21</a>; cf. 12:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:44</a>, 46; 18:25. <span class=\"greek\">τί</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔλαβες</span>; «que tens que não recebeste?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:7</a>.</p><p class=\"entry-text\">A abreviação <span class=\"greek\">ἔ</span>. é usada também neste sentido de posse. <strong>Acusativo objeto frequentemente acompanhado de adjetivo ou particípio:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">κοινά</span>, «ter todas as coisas em comum», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:44</a> (cf. Josefo, Ant. 15, 18). <span class=\"greek\">ἔ</span>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">κείμενα</span>, «ter muitos bens armazenados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a>. <strong>Uso absoluto</strong>, «ter alguma coisa» (Sófocles e outros; Sir 13:5; 14:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:25</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:18</a>a. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔχειν</span>, «conforme os recursos possuídos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:11</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπαρτισμόν</span>, «ter o suficiente para completar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:28</a>. Com negação, <strong>nada possuir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:25</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:18</a>b. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span>, «aquele que possui; o abastado» (Sófocles, Aj. 157; Eurípides, Alc. 57; Xenofonte, An. 7, 3, 28; Ar. 15:7). <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔχων</span>, «todo aquele que possui», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:29</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:26</a>a. <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχων</span>, «aquele que nada possui» (Xenofonte, An. 7, 3, 28; 1Esd 9:51, 54; 2Esd 18:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:29</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:26</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:22</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. A abreviação <span class=\"greek\">ἔ</span>. reaparece na fonte para esse verbo. <strong>Ter sob custódia ou guarda:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖς</span>, «ter as chaves», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:18</a>; cf. 3:7. <span class=\"greek\">τὸ</span> <span class=\"greek\">γλωσσόκομον</span>, «ter a bolsa [de dinheiro]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:6</a>; 13:29.</p><p class=\"entry-text\">ⓑ <strong>Conter algo, como o todo contém as partes.</strong></p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Seres vivos e partes do corpo humano ou animal:</strong> <span class=\"greek\">μέλη</span>, «membros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:4</a>a; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:12</a>. <span class=\"greek\">σάρκα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀστέα</span>, «carne e ossos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:39</a> (Justino, A I, 66, 2 <span class=\"greek\">καὶ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἷμα</span>, «carne e sangue»). <span class=\"greek\">ἀκροβυστίαν</span>, «prepúcio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:3</a>. <span class=\"greek\">οὖς</span>, «ouvido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:7</a>, 11; <span class=\"greek\">ὦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:8</a>. <span class=\"greek\">χεῖρας</span>, <span class=\"greek\">πόδας</span>, <span class=\"greek\">ὀφθαλμούς</span>, «mãos, pés e olhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:8</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:43</a>, 45, 47. Em animais e seres assemelhados: <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρόσωπον</span>, «ter rosto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:7</a>. <span class=\"greek\">πτέρυγας</span>, «asas», v. 8. <span class=\"greek\">κέρατα</span>, «chifres», 5:6. <span class=\"greek\">ψυχάς</span>, «vida», 8:9. <span class=\"greek\">τρίχας</span>, «pelos», 9:8. <span class=\"greek\">κεφαλάς</span>, «cabeças», 12:3 (TestAbr B 14, p. 118, 19 [Stone p. 84]) e outros. <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span>, «tendo a carne sadia», AcPlCor 2:32 (Justino, D. 48, 3 <span class=\"greek\">σάρκα</span> <span class=\"greek\">ἔχων</span>, «tendo carne»). <strong>Plantas:</strong> TestAbr B 3, p. 107, 6 [Stone p. 62] <span class=\"greek\">εὗρον</span> <span class=\"greek\">δένδρον</span> … <span class=\"greek\">ἔχον</span> <span class=\"greek\">κλάδους</span>, «encontraram uma árvore com ramos»; <span class=\"greek\">ῥίζαν</span> <span class=\"greek\">ἔ</span>., «ter raiz», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:6</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Coisas inanimadas:</strong> cidades <span class=\"greek\">τ</span>. <span class=\"greek\">θεμελίους</span> <span class=\"greek\">ἔ</span>., «ter fundamentos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:14</a>. De cobertura da cabeça: <span class=\"greek\">χαρακτῆρα</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">βασιλικόν</span>, «tem um emblema régio», GJs 2:2.</p><p class=\"entry-text\">ⓒ <strong>Ter à mão ou à disposição:</strong> <span class=\"greek\">ἄρτους</span>, «pães», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:17</a>; cf. 15:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:5</a> (provavelmente, «apanhastes algum peixe para o desjejum?»). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">παραθήσω</span> <span class=\"greek\">αὐτῷ</span>, «não tenho nada que lhe oferecer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:6</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐχόντων</span> <span class=\"greek\">τί</span> <span class=\"greek\">φάγωσι</span>, «como não tinham o que comer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:1</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a> (Sófocles, Oed. Col. 316 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">τί</span> <span class=\"greek\">φῶ</span>, «não tenho o que dizer»). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">συνάξω</span>, «não tenho onde recolher», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:17</a>. <span class=\"greek\">ἄντλημα</span>, «balde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:11</a>a. <span class=\"greek\">οἰκίας</span> <span class=\"greek\">ἔ</span>., «ter casas disponíveis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:22</a>. <strong>Pessoas à disposição:</strong> PAmh 92, 18 <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἕξω</span> <span class=\"greek\">κοινωνόν</span>, «não terei companheiro»; Moisés e os Profetas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:29</a>. <span class=\"greek\">παράκλητον</span>, «defensor; auxiliador», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:1</a>. <span class=\"greek\">οὐδένα</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἰσόψυχον</span>, «não tenho ninguém com o mesmo ânimo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:20</a>. <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔ</span>., «não tenho ninguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:7</a>.</p><p class=\"entry-text\">ⓓ <strong>Ter dentro de si:</strong> <span class=\"greek\">σύλλημα</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span>, «tem em si algo concebido pelo Espírito Santo», GJs 18:1. <strong>Construção com <span class=\"greek\">ἐν</span>:</strong> nas mulheres <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρὶ</span> <span class=\"greek\">ἔ</span>., «estar grávida» (ver <span class=\"greek\">γαστήρ</span> ②), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>, 23 (Is 7:14); 24:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:2</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span>, «ter alguém no coração», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:7</a> (Ovídio, Met. 2, 641 <em>aliquem clausum pectore habere</em>). <span class=\"greek\">ἔ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, «ter algo dentro de si» (Josefo, Ant. 8, 171; cf. TestAbr A 3, p. 80, 14 [Stone p. 8] <span class=\"greek\">ἔκρυψεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span>, <span class=\"greek\">μόνος</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτοῦ</span>, «ocultou o segredo, guardando-o só no coração»): <span class=\"greek\">ζωήν</span>, «vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:26</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">μαρτυρίαν</span>, «testemunho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:10</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀπόκριμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, «sentença de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:9</a>.</p><p class=\"entry-text\">ⓔ <strong>Ter consigo ou na companhia de alguém:</strong> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἑαυτοῦ</span> (Xenofonte, Cyr. 1, 4, 17) <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:30</a>; 26:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:19</a>; 14:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:8</a>; AcPl Ha 8, 35; <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span>, «com ele», AcPl Ha 4:18. <strong>Particípio com acusativo equivalente a «com»</strong> (Diodoro Sículo 12, 78, 1 <span class=\"greek\">ἔχων</span> <span class=\"greek\">δύναμιν</span>, «com uma força militar»; 18, 61, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">θρόνος</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">διάδημα</span>, «o trono com o diadema»; JosAs 27:8 <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ἐσπασμένας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ῥομφαίας</span>, «com as espadas desembainhadas»): <span class=\"greek\">ἀνέβησαν</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">αὐτόν</span>, «subiram com ele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:42</a>, códice D.</p><p class=\"entry-text\">② <strong>Manter uma relação próxima com alguém: ter por; ter como.</strong></p><p class=\"entry-text\">ⓐ <strong>Parentesco e casamento:</strong> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἔ</span>., «ter pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:41</a>; <span class=\"greek\">ἀδελφούς</span>, «irmãos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:28</a>. <strong>Da mulher, <span class=\"greek\">ἄνδρα</span>, «ter marido; ser casada»</strong> (Aristóteles, Cat. 15b, 27s. <span class=\"greek\">λεγόμεθα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἄνδρα</span>, «dizemos que o homem tem mulher e a mulher, marido»; Tb 3:8 BA), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:17</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:2</a>b, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:27</a> (Is 54:1). <strong>Do homem, <span class=\"greek\">γυναῖκα</span>, «ter mulher»</strong> (Luciano, Tox. 45; SIG 1160 <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">Αἴ</span>., <span class=\"greek\">τῆς</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔχει</span>; PGM 13, 320; 1Esd 9:12, 18; Justino, D. 141, 4 <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ἔσχον</span> <span class=\"greek\">γυναίκας</span>, «tiveram muitas mulheres»; desde Odisseia 11, 603, Héracles <span class=\"greek\">ἔχει</span> <span class=\"greek\">Ἥβην</span>, «tem Hebe»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:2</a>a, 12, 29 (para o jogo de palavras, Heliodoro 1, 18, 4 <span class=\"greek\">σὺ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἕξεις</span>, «tendo, não terás»; Crates, sétima carta [p. 58, 8 Malherbe] <span class=\"greek\">πάντ</span>’ <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἔχετε</span>, «possuindo tudo, nada possuís»). <span class=\"greek\">τέκνα</span>, «filhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:28</a>; 22:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3:4</a>; 5:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:6</a>. <span class=\"greek\">υἱούς</span>, «filhos homens» (Artemidoro 5, 42 <span class=\"greek\">τὶς</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">υἱούς</span>, «alguém com três filhos»; cf. <span class=\"greek\">θυγατέρα</span> em TestAbr B 10, p. 114, 17 [Stone p. 76]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:22</a>. <span class=\"greek\">σπέρμα</span>, «descendência; filhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:25</a>.</p><p class=\"entry-text\"><strong>Acusativo objeto com predicativo acusativo:</strong> Ar. 8, 4 <span class=\"greek\">τούτους</span> <span class=\"greek\">συνηγόρους</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span>, «tendo-os como defensores da maldade»; 11, 3 <span class=\"greek\">ἔσχε</span> <span class=\"greek\">μοιχὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἄρην</span>, «teve Ares como adúltero»; Atenágoras 7, 2 <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">προφήτας</span> <span class=\"greek\">μάρτυρας</span>, «temos profetas como testemunhas». <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">πατέρα</span>, «ter alguém por pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:9</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">γυναῖκα</span> (a segunda ocorrência de <span class=\"greek\">γυναῖκα</span> é subentendida no contexto), «ter alguém por mulher», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:18</a>. <span class=\"greek\">ὥστε</span> <span class=\"greek\">γυναῖκά</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἔ</span>., «de maneira que alguém tenha a mulher do próprio pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:1</a>. Pode referir-se a casamento (Plutarco, Cato Min. 21, 3; Apiano, Bell. Civ. 3, 10 §34; Josefo, C. Ap. 1, 147) ou a relacionamento ilícito (Longo 4, 17; Hesíquio de Mileto [séc. VI d.C.], <em>Viri Illustres</em> 4, J. Flach [1880], <span class=\"greek\">ἔχω</span> <span class=\"greek\">Λαί̈δα</span>; Diodoro Sículo 20, 33, 5, sobre relações secretas com a madrasta: <span class=\"greek\">ἔχειν</span> <span class=\"greek\">λάθρᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀλκίαν</span>). A fonte preserva a incerteza contextual.</p><p class=\"entry-text\">ⓑ <strong>Relações pessoais de maneira geral:</strong> <span class=\"greek\">φίλον</span>, «ter amigo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:5</a>. <span class=\"greek\">ἀσθενοῦντας</span>, «enfermos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:40</a>, e <span class=\"greek\">χήρας</span>, «viúvas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:16</a>, sob cuidados; <span class=\"greek\">παιδαγωγοὺς</span> <span class=\"greek\">ἔ</span>., «ter tutores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:15</a>. <span class=\"greek\">δοῦλον</span>, «servo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:7</a>. <span class=\"greek\">οἰκονόμον</span>, «administrador», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:1</a>. <span class=\"greek\">κύριον</span> <span class=\"greek\">ἔ</span>., «ter senhor; estar subordinado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:1</a>; <span class=\"greek\">δεσπότην</span> <span class=\"greek\">ἔ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:2</a>. <span class=\"greek\">βασιλέα</span>, «rei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:15</a>. <span class=\"greek\">ἀρχιερέα</span>, «sumo sacerdote», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:14</a>; 8:1. <span class=\"greek\">ποιμένα</span>, «pastor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:36</a>. <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">στρατιώτας</span>, «tendo soldados sob meu comando», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:8</a>. <strong>Acusativo com predicativo:</strong> <span class=\"greek\">ἔχειν</span>, «ter», reaparece nas construções; <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὑπηρέτην</span>, «ter alguém como assistente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:5</a> (Justino, A I, 14, 1); <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">τύπον</span>, «ter alguém como exemplo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:17</a>. <strong>Relacionamento cristão com Deus e Jesus:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">θεόν</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span>, «ter Deus, o Pai e o Filho», isto é, «estar em comunhão com eles», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 9</a>; AcPl Ha 4, 7. Bibliografia específica sobre «ter Deus»: H. Hanse, ao fim da entrada.</p><p class=\"entry-text\">③ <strong>Segurar ou tomar posse de algo: ter nas mãos; reter; agarrar.</strong></p><p class=\"entry-text\">ⓐ <strong>Segurar nas mãos:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρί</span>, «ter algo na mão» (desde Ilíada 18, 505), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:16</a>; 6:5; 10:2; 17:4. Sem <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρί</span> (Js 6:8; JosAs 5:7), <span class=\"greek\">ἔ</span>. <span class=\"greek\">κιθάραν</span>, «ter uma cítara», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:8</a>; <span class=\"greek\">λιβανωτὸν</span> <span class=\"greek\">χρυσοῦν</span>, «incensário de ouro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:3</a>, cf. v. 6; 14:17; ver <span class=\"greek\">ἀλάβαστρον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:3</a>.</p><p class=\"entry-text\">ⓑ <strong>Guardar alguma coisa com segurança:</strong> conservar uma mina (remuneração de cerca de três meses de trabalhador) num lenço, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:20</a>.</p><p class=\"entry-text\">ⓒ <strong>Reter firmemente coisas de importância transcendente, figuradamente:</strong> <span class=\"greek\">τὴν</span> <span class=\"greek\">μαρτυρίαν</span>, «o testemunho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:9</a>; 12:17; 19:10. Guardar o mistério da piedade cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3:9</a>, ou modelo de sã doutrina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:13</a>. <strong>Manter sob controle</strong> (Diodoro Sículo 17, 93, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">ἔχειν</span>, «reter o reino»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:18</a>.</p><p class=\"entry-text\">ⓓ <strong>Estados que dominam ou dominam alguém: apoderar-se; tomar de assalto; subjugar</strong> (Homero e outros; PGiss 65a, 4 <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">σε</span> <span class=\"greek\">κύριέ</span> <span class=\"greek\">μου</span>, <span class=\"greek\">εἰδότα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔχουσάν</span> <span class=\"greek\">με</span> <span class=\"greek\">συμφορὰν</span> <span class=\"greek\">ἀπολῦσαί</span> <span class=\"greek\">μοι</span>, «peço-te, meu senhor, que, conhecendo a adversidade que me domina, me libertes»; Jó 21:6; Is 13:8; Josefo, Ant. 3, 95 <span class=\"greek\">δέος</span> <span class=\"greek\">εἶχε</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Ἑβρ</span>., «o temor dominava os hebreus»; 5, 63; Justino, D. 19, 3). <span class=\"greek\">εἶχεν</span> <span class=\"greek\">αὐτὰς</span> <span class=\"greek\">τρόμος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔκστασις</span>, «tremor e assombro se apoderaram delas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:8</a>.</p><p class=\"entry-text\">④ <strong>Trazer ou portar como acessório ou parte de um conjunto: vestir; usar; portar</strong> — roupas, armas e semelhantes (Homero e outros; LXX; TestAbr B, p. 114, 22 [Stone p. 76]). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔνδυμα</span>, «a roupa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; 22:12 (cf. <span class=\"greek\">ἔνδυσιν</span>, TestJob 25:7). <span class=\"greek\">κατὰ</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">ἔχων</span>, com <span class=\"greek\">τὶ</span> subentendido, «tendo [algo] sobre a cabeça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:4</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">θώρακας</span>, «usar couraças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:9</a>, 17. <span class=\"greek\">ἔ</span>. <span class=\"greek\">μάχαιραν</span>, «portar espada» (Josefo, Ant. 6, 190), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:10</a>. <strong>Árvores:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">φύλλα</span>, «ter folhas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:13</a> (ApcSed 8:8).</p><p class=\"entry-text\">⑤ <strong>Estar em condição de fazer alguma coisa: poder; ser capaz de.</strong> <span class=\"greek\">ἔχω</span> seguido de infinitivo (Homero e outros; Eurípides, Hec. 761; Heródoto 1, 49; Platão, Phd. 76d; Demóstenes, Ep. 2, 22; Teócrito 10, 37 <span class=\"greek\">τὸν</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">εἰπεῖν</span>, «não posso especificar o modo»; Luciano, Dial. Mort. 21, 2; Hermot. 55; Epicteto 1, 9, 32; 2, 2, 24 e outros; Élio Aristides 51, 50 K. = 27, p. 546 D. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">λέγειν</span>, «não tenho como falar»; PPetr II, 12, 1, 16; PAmh 131, 15; Pv 3:27; ApcEsdr 2:24; 3:7; 6:5; TestAbr A 8, p. 86, 13 [Stone p. 20]; Josefo, Ant. 1, 338; 2, 58; Justino, A I, 19, 5; D. 4, 6 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">εἰπεῖν</span>). <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἀποδοῦναι</span>, «poder pagar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:25</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:42</a>; 14:14. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">περισσότερον</span> <span class=\"greek\">τι</span> <span class=\"greek\">ποιῆσαι</span>, «não poder fazer mais coisa alguma», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:4</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἀντειπεῖν</span>, «não ter como responder», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:8</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">κατηγορεῖν</span> <span class=\"greek\">αὐτοῦ</span>, «ter como acusá-lo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:6</a> (ver ⑨ⓐ, adiante). <span class=\"greek\">ἀσφαλές</span> <span class=\"greek\">τι</span> <span class=\"greek\">γράψαι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχω</span>, «não tenho nada de seguro a escrever», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:26</a>a; cf. 26b. <span class=\"greek\">ἔ</span>. <span class=\"greek\">μεταδιδόναι</span>, «poder repartir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:28</a>a. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">μνήμην</span> <span class=\"greek\">ποιεῖσθαι</span>, «poder recordar tais coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:15</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">μείζονος</span> <span class=\"greek\">ὀμόσαι</span>, «não podia jurar por ninguém maior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:13</a>. Sem infinitivo expresso, mas inferível pelo contexto (Xenofonte, An. 2, 1, 9): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἔσχεν</span> (isto é, <span class=\"greek\">ποιῆσαι</span>) <span class=\"greek\">ἐποίησεν</span>, «ela fez tudo quanto pôde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:8</a>.</p><p class=\"entry-text\">⑥ <strong>Ter determinada opinião sobre algo ou alguém: considerar; julgar; reputar</strong>, com acusativo objeto e acusativo predicativo (POxy 292, 6 [cerca de 25 d.C.] <span class=\"greek\">ἔχειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">συνεσταμένον</span>, «considerá-lo recomendado»; 787 [16 d.C.]; PGiss 71, 4; Jó 30:9; Ps.-Clemente, Hom. 16, 19; Atenágoras 32, 3 <span class=\"greek\">τοὺς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">υἱοὺς</span> … <span class=\"greek\">νοοῦμεν</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀδελφούς</span> <span class=\"greek\">ἔχομεν</span>, «entendemos uns como filhos e temos outros como irmãos»). <span class=\"greek\">ἔχε</span> <span class=\"greek\">με</span> <span class=\"greek\">παρῃτημένον</span>, «considera-me escusado», isto é, «não esperes que eu vá», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:18</a>b, 19 (cf. Marcial 2, 79, <em>excusatum habeas me</em>). <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔντιμον</span> <span class=\"greek\">ἔ</span>., «ter alguém em honra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:29</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">προφήτην</span>, «considerar alguém profeta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:5</a>; 21:26, 46, variante (cf. GNicod 5 [Acta Pilati B 5, p. 297 Tdf.] <span class=\"greek\">ἔχειν</span> [Janes e Jambres] <span class=\"greek\">ὡς</span> <span class=\"greek\">θεούς</span>, «considerá-los deuses»; Justino, D. 47, 5 <span class=\"greek\">τὸν</span> <span class=\"greek\">μετανοοῦντα</span> … <span class=\"greek\">ὡς</span> <span class=\"greek\">δίκαιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναμάρτητον</span> <span class=\"greek\">ἔχει</span>, «considerar o arrependido justo e sem pecado»). <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">προφήτην</span>, «considerar alguém profeta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:46</a> (cf. Dúris, séc. III a.C., 76 Fgm. 21 Jac. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἔχουσιν</span>, «aquele que contam entre os deuses»). <span class=\"greek\">εἶχον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰωάννην</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">ἦν</span>, «consideravam que João era realmente profeta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:32</a>.</p><p class=\"entry-text\">⑦ <strong>Passar por determinada experiência; experimentar; ter</strong>, frequentemente como verbo auxiliar (C. Turner, JTS 28 [1927], 357–60).</p><p class=\"entry-text\">ⓐ <strong>Condições do corpo e da alma</strong> (Homero e posteriores; LXX).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Doença e sofrimento</strong> (ApcMos 6 <span class=\"greek\">νόσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πόνον</span> <span class=\"greek\">ἔχω</span>, «tenho enfermidade e dor»; Josefo, C. Ap. 1, 305). <span class=\"greek\">ἀσθενείας</span>, «ter enfermidades», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:9</a>. <span class=\"greek\">μάστιγας</span>, «aflições físicas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:10</a>. <span class=\"greek\">πληγὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μαχαίρης</span>, «ferida da espada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:14</a>. <span class=\"greek\">θλῖψιν</span>, «tribulação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:33</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:10</a>. <strong>Especialmente possessão por espíritos hostis:</strong> <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">ἔ</span>., «ter demônio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:33</a>; 8:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:20</a>; 8:48s., 52; 10:20. <span class=\"greek\">Βεελζεβούλ</span>, «Belzebu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:22</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἀκάθαρτον</span>, «espírito impuro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:30</a>; 7:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:7</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">δαιμονίου</span> <span class=\"greek\">ἀκαθάρτου</span>, «espírito de demônio impuro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:33</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πονηρόν</span>, «espírito maligno», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:13</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἄλαλον</span>, «espírito mudo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:17</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἀσθενείας</span>, «espírito de enfermidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:11</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">λεγιῶνα</span>, «a Legião» (nome atribuído ao espírito maligno), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Condições, qualidades, capacidades, sentimentos e posses interiores em geral:</strong> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ἔ</span>., «ter amor» (cf. Diodoro Sículo 3, 58, 3 <span class=\"greek\">φιλίαν</span> <span class=\"greek\">ἔχειν</span>, «ter amizade»; Justino, D. 93, 4 <span class=\"greek\">φιλίαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ἔχοντε</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:42</a>; 13:35; 15:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:1</a>ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:8</a>. <span class=\"greek\">ἀγνωσίαν</span> <span class=\"greek\">θεοῦ</span>, «ter ignorância de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:34</a>. <span class=\"greek\">ἁμαρτίαν</span>, «ter pecado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:41</a>; 15:22a. <span class=\"greek\">ἀσθένειαν</span>, «ter fraqueza», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:28</a>. <span class=\"greek\">γνῶσιν</span>, «ter conhecimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8:1</a>, 10 (Justino, A II, 13, 1; D. 28, 4). <span class=\"greek\">ἐλπίδα</span>, «ter esperança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:12</a>; 10:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:3</a> (Atenágoras 33, 1). <span class=\"greek\">ἐπιθυμίαν</span>, «desejo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:23</a>. <span class=\"greek\">ἐπιποθίαν</span>, «anseio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:23</a>b. <span class=\"greek\">ζῆλον</span> <span class=\"greek\">ἔ</span>., «ter zelo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:2</a>. <strong>Ciúmes ou inveja</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:14</a>. <span class=\"greek\">θυμόν</span>, «ira», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:12</a>. <span class=\"greek\">λύπην</span>, «tristeza» (ApcMos 3, p. 2, 16 Tdf.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:21</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:27</a>. <span class=\"greek\">μνείαν</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">ἔ</span>., «guardar lembrança de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:6</a>. <span class=\"greek\">παρρησίαν</span>, «franqueza; confiança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:28</a>; 3:21; 4:17; 5:14. <span class=\"greek\">πεποίθησιν</span>, «confiança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:4</a>. <span class=\"greek\">πίστιν</span>, «fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>; 21:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:19</a> e outros (Justino, A I, 52, 1). <span class=\"greek\">προφητείαν</span>, «dom profético», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:2</a>. <span class=\"greek\">σοφίαν</span>, «sabedoria» (Xenofonte, Mem. 2, 3, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:9</a>. <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">ἁμαρτιῶν</span>, «consciência dos pecados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:2</a>. <span class=\"greek\">καλὴν</span> <span class=\"greek\">συνείδησιν</span>, «boa consciência», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>; <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">ς</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:16</a>; <span class=\"greek\">ἀπρόσκοπον</span> <span class=\"greek\">ς</span>., «consciência sem tropeço», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:16</a>. <span class=\"greek\">ὑπομονήν</span>, «perseverança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:3</a>. <span class=\"greek\">φόβον</span>, «temor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:20</a>. <span class=\"greek\">χαράν</span>, «alegria», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 7</a>. <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινί</span>, «ser agradecido a alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:3</a>. <span class=\"greek\">σιγὴν</span> <span class=\"greek\">ἔ</span>., «manter silêncio», Hs 9, 11, 5. <span class=\"greek\">ἀνάγκην</span> <span class=\"greek\">ἔσχον</span>, «senti necessidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 3</a> (H. Koskenniemi, <em>Studien zur Idee und Phraseologie des Griechischen Briefes bis 400 n. Chr.</em> [1956], 78–87).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Vantagens, benefícios ou confortos experimentados:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">αἰτήματα</span>, «ter obtido os pedidos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:15</a>; <span class=\"greek\">ἀνάπαυσιν</span> <span class=\"greek\">ἔ</span>., «ter descanso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:8</a>; 14:11; <span class=\"greek\">ἀπόλαυσιν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἔ</span>., «usufruir de algo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:25</a>. <span class=\"greek\">βάθος</span> <span class=\"greek\">γῆς</span>, «profundidade da terra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:5</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:5</a>b. <span class=\"greek\">γῆν</span> <span class=\"greek\">πολλήν</span>, «muita terra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:5</a>a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:5</a>a. <span class=\"greek\">τὴν</span> <span class=\"greek\">προσέλευσιν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, «acesso ao Senhor», AcPl Ha 8, 22s.; <span class=\"greek\">εἰρήνην</span>, «paz», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:1</a>. <span class=\"greek\">ἐλευθερίαν</span>, «liberdade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:4</a>. Ver também <span class=\"greek\">ἐξουσία</span>, <span class=\"greek\">ἐπαγγελία</span>, <span class=\"greek\">ἔπαινος</span>, <span class=\"greek\">ζωή</span>, <span class=\"greek\">ἰκμάς</span>, <span class=\"greek\">καιρός</span>, <span class=\"greek\">καρπός</span>, <span class=\"greek\">καύχημα</span>, <span class=\"greek\">καύχησις</span>, <span class=\"greek\">λόγος</span>, <span class=\"greek\">μισθός</span>, <span class=\"greek\">νοῦς</span>, <span class=\"greek\">πνεῦμα</span>, <span class=\"greek\">προσαγωγή</span>, <span class=\"greek\">πρόφασις</span>, <span class=\"greek\">τιμή</span>, <span class=\"greek\">χάρις</span> («favor»), <span class=\"greek\">χάρισμα</span>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <strong>Sentimento de obrigação ou necessidade perante alguma coisa.</strong> Com objeto direto, «ter algo imposto; estar sujeito a algo»: <span class=\"greek\">ἀνάγκην</span> <span class=\"greek\">ἔχειν</span>, «estar sob necessidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:37</a>a. Com infinitivo, «ter de fazer; necessitar» (ver <span class=\"greek\">ἀνάγκη</span> ①), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:18</a>; 23:16, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a>. <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔ</span>., «ter necessidade», uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:28</a>b; <strong>com genitivo <span class=\"greek\">τινός</span></strong>, «necessitar de algo» (Ésquilo e outros; SIG 333, 20; 421, 35; PPetr III, 42 G 9, 7 [séc. III a.C.] <span class=\"greek\">ἐάν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχῃς</span>, «se tiveres necessidade de algo»; Atenágoras 13, 2 <span class=\"greek\">ποίας</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἑκατόμβης</span> <span class=\"greek\">ἔχει</span>;), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:8</a>; 9:12a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:31</a>, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:36</a> e outros. <strong>Seguido de infinitivo</strong> (TestSol 13:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:14</a>; 14:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:8</a>; 4:9; 5:1. <span class=\"greek\">νόμον</span>, «lei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:7</a>. <span class=\"greek\">ἐπιταγήν</span>, «mandamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:25</a>. <span class=\"greek\">ἐντολήν</span>, «preceito» (SIG 559, 9 <span class=\"greek\">ἔ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἰντολάς</span>; 1Esd 4:52; 2Mc 3:13; Josefo, Bell. 1, 261), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:7</a>; 4:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14:21</a>. <span class=\"greek\">διακονίαν</span>, «ministério», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:1</a>. <span class=\"greek\">ἀγῶνα</span>, «combate», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:1</a>. <span class=\"greek\">πρᾶξιν</span>, «atividade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:4</a>b. <span class=\"greek\">ἔγκλημα</span>, «acusação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:29</a>. <span class=\"greek\">κόλασιν</span>, «castigo», ApcPt Bodl. (ApcEsdr 1:22, p. 25, 17 Tdf.).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. <strong>Necessidade inevitável de determinada ação:</strong> seguido de infinitivo, «precisar; dever; ser obrigado a» (Ps.-Calístenes 2, 1, 3 <span class=\"greek\">καθαιρεθῆναι</span> <span class=\"greek\">ἔχεις</span>, «deves ser deposto»; Porfírio, <em>Against the Christians</em> 63 Harnack [ABA 1916] <span class=\"greek\">παθεῖν</span>; Gn 18:31; Josefo, Ant. 19, 348 <span class=\"greek\">τοῦ</span> <span class=\"greek\">τεθνάναι</span>; TestSol 5:12 <span class=\"greek\">σίδηρα</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">φορέσαι</span>, «tens de usar ferros»; TestAbr A 18, p. 100, 22 [Stone p. 48] <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">τοῦτου</span> <span class=\"greek\">ἀπαλλάξαι</span> <span class=\"greek\">εἶχες</span>, «tiveste de deixar esta vida»; Justino, D. 51, 2 <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">πεισθήναι</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐχόντων</span>). <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">βαπτισθῆναι</span>, «tenho de passar por um batismo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:50</a>. <span class=\"greek\">ἔχω</span> <span class=\"greek\">σοί</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἰπεῖν</span>, «tenho algo para te dizer» (Luciano, Philops. 1 <span class=\"greek\">ἔχεις</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰπεῖν</span>; sem dativo, Eliano, VH 2, 23; Josefo, Ant. 16, 312), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:40</a>. <span class=\"greek\">καινόν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">θέαμα</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">ἐξηγήσασθαι</span>, «tenho de te contar uma visão extraordinária que tive», GJs 19:3. <span class=\"greek\">ἀπαγγεῖλαι</span>, «relatar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:17</a>, 19; cf. v. 18. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">γράφειν</span>, «escrever muitas coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 13</a>.</p><p class=\"entry-text\">ⓑ <strong>Circunstâncias temporais, idade e duração:</strong> <span class=\"greek\">πεντήκοντα</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">οὔπω</span> <span class=\"greek\">ἔχεις</span>, «ainda não tens cinquenta anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.57\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:57</a> (cf. Josefo, Ant. 1, 198). <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὀκτὼ</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀσθενείᾳ</span> <span class=\"greek\">αὐτοῦ</span>, «enfermo havia trinta e oito anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:5</a> (Cyranides, p. 63, 25 <span class=\"greek\">πολὺν</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀρρωστίᾳ</span>, «enfermo durante longo tempo»; com cardinal, TestJob 26:1 <span class=\"greek\">δέκα</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πληγαῖς</span>, «há dezessete anos estou afligido»; POxy 1862, 17 <span class=\"greek\">τέσσαρες</span> <span class=\"greek\">μῆνας</span> <span class=\"greek\">ἔχει</span>, «tem quatro meses»; <em>Miracula S. Georgii</em> 44, 7 [J. Aufhauser, 1913] <span class=\"greek\">ἔσχεν</span> … <span class=\"greek\">ἔτη</span> <span class=\"greek\">ἑπτά</span>, «passaram sete anos»). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:20</a>, variante. <span class=\"greek\">τέσσαρας</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μνημείῳ</span>, «estar no túmulo há quatro dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:17</a> (Josefo, Ant. 7, 1 <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἔχοντος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Σεκέλλᾳ</span>). <span class=\"greek\">πολὺν</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">ἔ</span>., «estar por muito tempo em determinado lugar ou estado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:6</a>. <span class=\"greek\">ἡλικίαν</span> <span class=\"greek\">ἔχειν</span>, «ter idade; ser maior de idade» (Platão, Euthyd. 32, 306d; Plutarco, Mor. 547a; BGU 168 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀτελέσι</span> <span class=\"greek\">ἔχουσι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡλικίαν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:21</a>, 23. <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχειν</span>, «ter fim; terminar» (Luciano, Charon 17; UPZ 81 III, 20 [séc. II d.C.] <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πάντα</span>, «tudo termina»; Ar. 4:2 <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέλος</span>, «começo e fim»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:37</a> (ver <span class=\"greek\">τέλος</span> ②); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a>.</p><p class=\"entry-text\">⑧ <strong>Como marcador de conexão entre entidades: produzir; acarretar; implicar</strong>, com acusativo (Homero e outros; Wsd 8:16). Da <span class=\"greek\">ὑπομονή</span>, «perseverança»: <span class=\"greek\">ἔργον</span> <span class=\"greek\">τέλειον</span>, «obra perfeita», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:4</a>. Da <span class=\"greek\">πίστις</span>, «fé»: <span class=\"greek\">ἔργα</span>, «obras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:17</a>. De <span class=\"greek\">φόβος</span>, «temor»: <span class=\"greek\">κόλασιν</span>, «castigo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:18</a>. De <span class=\"greek\">παρρησία</span>, «franqueza»: <span class=\"greek\">μεγάλην</span> <span class=\"greek\">μισθαποδοσίαν</span>, «grande recompensa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:35</a>. De <span class=\"greek\">πολυτέλεια</span>, «luxo»: <span class=\"greek\">λύπην</span>, <span class=\"greek\">χαράν</span>, «tristeza, alegria», Hs 1, 10. <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">εὐλογίαν</span>, <span class=\"greek\">ἥτις</span> <span class=\"greek\">διαδοχὴν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span>, «bênção última, sem sucessora», GJs 6:2.</p><p class=\"entry-text\">⑨ <strong>Construções e locuções especiais.</strong></p><p class=\"entry-text\">ⓐ <strong>Com preposições:</strong> <strong><span class=\"greek\">ἐν</span></strong>, <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιγνώσει</span>, «reconhecer Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:28</a> (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀργῇ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινά</span>, «estar irado com alguém», Tucídides 2, 18, 5; 2, 21, 3; <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀρρωδίᾳ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>., «ter temor de alguém», 2, 89, 1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡδονῇ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>., «alegrar-se ao ver alguém», 3, 9, 1; <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐνοίᾳ</span> <span class=\"greek\">ἔ</span>., «estar bem-disposto», Demóstenes 18, 167). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span> <span class=\"greek\">ἔ</span>., «ter à disposição; estar preparado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:6</a> (ver <span class=\"greek\">ἕτοιμος</span> b). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">οὐδέν</span>, «nada tem em mim», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14:30</a> (Apiano, Bell. Civ. 3, 32 §125 <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «depositar alguma esperança de segurança em alguém»). <strong><span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>:</strong> para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:4</a>, ver ④. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, «ter algo contra alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:25</a>; com <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:14</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, mesmo sentido, Hm 2:2; Hs 9, 23, 2; com <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:4</a>, 20. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσωπον</span>, «encontrar alguém face a face», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:16</a>. <strong><span class=\"greek\">μετά</span>:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, «ter algo com alguém», <span class=\"greek\">κρίματα</span>, «contendas judiciais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:7</a>. <strong><span class=\"greek\">περί</span>:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «ter palavra, comentário ou explicação sobre algo», B 12:1; com advérbio <span class=\"greek\">τελείως</span>, B 10:10. <strong><span class=\"greek\">πρός</span>:</strong> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «ter algo contra alguém» (Ps.-Calístenes 2, 21, 21 <span class=\"greek\">ὅσον</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἕτερον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:19</a>. <span class=\"greek\">ζητήματα</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «ter controvérsias com alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:19</a>. <span class=\"greek\">λόγον</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «ter uma demanda contra alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:38</a>. <span class=\"greek\">πρᾶγμα</span> (latim <em>causa</em>, «ação judicial»: BGU 19 I, 5; 361 II, 4) <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (POxy 743, 19 [2 a.C.] <span class=\"greek\">εἰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἄλλους</span> <span class=\"greek\">εἶχον</span> <span class=\"greek\">πρᾶγμα</span>, «se tivesse demanda contra outros»; BGU 22:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:1</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔχωσιν</span> <span class=\"greek\">κατηγορίαν</span> <span class=\"greek\">αὐτοῦ</span>, «a fim de que tivessem acusação contra ele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:4</a>, códice D (cf. ⑤ acima). <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">μομφήν</span>, «ter queixa contra alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:13</a>.</p><p class=\"entry-text\">ⓑ <strong>Outras expressões:</strong> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">ὅτι</span>, «tens isto a teu favor: que…», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:6</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὁδόν</span>, «estar a certa distância de» (cf. <em>Periplus Maris Erythraei</em> 37, <span class=\"greek\">Ὡραία</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θαλάσσης</span>, «Oraia, situada a sete dias de viagem do mar»). Sobre o monte das Oliveiras, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">σαββάτου</span> <span class=\"greek\">ἔχον</span> <span class=\"greek\">ὁδόν</span>, «que fica perto de Jerusalém, à distância de uma jornada sabática», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:12</a>. <span class=\"greek\">ἴδε</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σόν</span>, «vê, aí tens o que é teu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:25</a>. <span class=\"greek\">ἔχετε</span> <span class=\"greek\">κουστωδίαν</span>, «aí tendes uma guarda; podeis dispor de uma guarda», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:65</a> (cf. POxy 33 III, 4).</p><p class=\"entry-text\">⑩ <strong>Encontrar-se em determinado estado ou condição: estar</strong>, ativa intransitiva (espacialmente, Atenágoras 25, 1 <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄγγελοι</span> … <span class=\"greek\">περὶ</span> <span class=\"greek\">τόν</span> <span class=\"greek\">ἀέρα</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, «os anjos ocupando o ar e a terra»), com advérbio (Homero e posteriores; inscrições, papiros, LXX).</p><p class=\"entry-text\">ⓐ <strong>Impessoal: estar a situação de determinado modo</strong> (Himério, Or. 48 [= Or. 14], 10 <span class=\"greek\">πῶς</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">δοκεῖ</span>; «como vos parece estar esta situação?»; Justino, D. 3, 5 <span class=\"greek\">τὸ</span> … <span class=\"greek\">ὡσαύτως</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">ἔχων</span>). <span class=\"greek\">ἄλλως</span>, «de outro modo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:25</a>. <span class=\"greek\">οὕτως</span>, «assim» (Antígono de Caristo 20; Cebes 4, 1; POxy 294, 11 [22 d.C.] <span class=\"greek\">εἰ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔχει</span>, «se tais coisas são assim»; TestSol 20:8; Josefo, Ant. 15, 261; Justino, D. 3:5 <span class=\"greek\">οὐχ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔχει</span>, «não é assim»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:1</a>; 12:15; 17:11; 24:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἔχον</span>, «o que é correto» (Michel 543, 12 [cerca de 200 a.C.] <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἔχον</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τιμᾶσθαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">εὔνους</span> <span class=\"greek\">ἄνδρας</span>), 1Cl 14:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔχον</span>, «por enquanto; no presente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:25</a> (cf. Plutarco, Mor. 749a; Luciano, Anachars. 40; Catapl. 13 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔχον</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διάτριβε</span>, «por ora, não demores»; Tb 7:11).</p><p class=\"entry-text\">ⓑ <strong>Pessoal: estar em determinada condição:</strong> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἔχουσιν</span>, «como estão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:36</a> (Gn 43:27; Josefo, Ant. 4, 112). <span class=\"greek\">ἑτοίμως</span> <span class=\"greek\">ἔ</span>., «estar preparado; disponível», seguido de infinitivo (BGU 80, 17 [séc. II d.C.] <span class=\"greek\">ἡ</span> <span class=\"greek\">Σωτηρία</span> <span class=\"greek\">ἑτοίμως</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">καταγράψαι</span>; Dn 3:15 LXX; Josefo, Ant. 13, 6; Justino, D. 50, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:5</a>. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span> <span class=\"greek\">ἔ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:6</a> (ver <span class=\"greek\">ἕτοιμος</span> b). <span class=\"greek\">εὖ</span> <span class=\"greek\">ἔ</span>., «estar bem-disposto», <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «para com alguém», Hs 9, 10, 7 (Demóstenes 9, 63 <span class=\"greek\">ἥδιον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>; SIG 1094, 4 <span class=\"greek\">φιλανθρώπως</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάντας</span>). <span class=\"greek\">κακῶς</span> <span class=\"greek\">ἔ</span>., «estar enfermo» (Aristófanes e outros; POxy 935, 15; Ez 34:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; 8:16; 9:12b; 17:15, variante (ver <span class=\"greek\">πάσχω</span> ②). <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἔ</span>., «estar bem; ter saúde» (Epicteto 1, 11, 4; PGen 54, 8; PFlor 230, 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:18</a>; <span class=\"greek\">ἐσχάτως</span> <span class=\"greek\">ἔ</span>., «estar em estado extremo» (ver <span class=\"greek\">ἐσχάτως</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:23</a>. <span class=\"greek\">κομψότερον</span> <span class=\"greek\">ἔ</span>., «estar melhor de saúde» (<span class=\"greek\">κομψῶς</span> <span class=\"greek\">ἔ</span>. em Epicteto 2, 18, 14; 3, 10, 13; PParis 18; PTebt 414, 10 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">κομψῶς</span> <span class=\"greek\">σχῶ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:52</a>.</p><p class=\"entry-text\">⑪ <strong>Estar estreitamente associado ou situado próximo: manter-se ligado; estar junto; seguir-se</strong>, voz média (Homero e posteriores); no NT, somente no particípio.</p><p class=\"entry-text\">ⓐ <strong>Associação por pertencimento íntimo: apegar-se; estar ligado a</strong>, genitivo de pertencimento e de associação (Teógnis 1, 32 <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span> <span class=\"greek\">ἔχεο</span>, «mantém-te sempre junto aos bons»; Xenofonte, Oec. 6, 1; Platão, Leg. 7, 811d; Luciano, Hermot. 69 <span class=\"greek\">ἐλπίδος</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μικρᾶς</span> <span class=\"greek\">ἐχόμενα</span> <span class=\"greek\">λέγεις</span>, «dizes coisas ligadas a esperança não pequena»; Salústio 14, p. 26, 24 <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span>; Fílon, Agr. 101 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">ἐχόμενα</span>; Josefo, Ant. 10, 204 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἀνθρωπίνης</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">ἐχόμενον</span>, «nada ligado à sabedoria humana»; C. Ap. 1, 83 <span class=\"greek\">παλαιᾶς</span> <span class=\"greek\">ἱστορίας</span> <span class=\"greek\">ἐχόμενον</span>; Justino, A I, 68, 1 <span class=\"greek\">λόγου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">ἔχεσθαι</span>; Taciano 33, 1 <span class=\"greek\">μανίας</span> <span class=\"greek\">ἔχεται</span> <span class=\"greek\">πολλῆς</span>, «está tomado por grande loucura»; Atenágoras, R. 48, 3 <span class=\"greek\">λόγῳ</span> … <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">ἐχομένῳ</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐχόμενα</span> <span class=\"greek\">σωτηρίας</span>, «coisas que acompanham a salvação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:9</a>.</p><p class=\"entry-text\">ⓑ <strong>Proximidade.</strong> <span class=\"greek\">α</span>. <strong>Espacial: vizinho; adjacente.</strong> <span class=\"greek\">ἐχόμενος</span>, «vizinho; próximo» (Isócrates 4, 96, <span class=\"greek\">νῆσος</span>, «ilha»; Heródoto 1, 134 <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐχόμενοι</span>, «os vizinhos»; Diodoro Sículo 5, 15, 1; Apiano, Bell. Civ. 2, 71 §294; Arriano, Peripl. 7, 2; PParis 51, 5, frequentemente em papiros; 1Esd 4:42; Josefo, Ant. 6, 6 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐχομένας</span> <span class=\"greek\">πόλεις</span>, «às cidades próximas»; 11, 340): <span class=\"greek\">κωμοπόλεις</span>, «povoados vizinhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:38</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Temporal: seguinte; imediatamente posterior</strong> (Tucídides 6, 3, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">ἐχομένου</span> <span class=\"greek\">ἔτους</span>; SIG 800, 15; PRev 34, 20; PAmh 49, 4; PTebt 124, 43; LXX). <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐχομένῃ</span>, com <span class=\"greek\">ἡμέρᾳ</span> subentendido [ou <span class=\"greek\">ἡμέραν</span> após <span class=\"greek\">εἰς</span>] (Políbio 3, 112, 1; 5, 13, 9; 2Mc 12:39; Josefo, Ant. 6, 235; 7, 18; cf. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐχομένην</span> em PMich 173, 16 [séc. III a.C.]), «no dia seguinte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:33</a> (variante <span class=\"greek\">ἐρχομένῃ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:15</a>. Com <span class=\"greek\">ἡμέρᾳ</span> expresso (PAmh 50, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:26</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐχομένῳ</span> <span class=\"greek\">σαββάτῳ</span>, «no sábado seguinte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:44</a>, variante de <span class=\"greek\">ἐρχομένῳ</span> (cf. 1Mc 4:28, os testemunhos também divergem).</p><p class=\"entry-text\"><strong>Bibliografia geral:</strong> H. Hanse, <em>«Gott Haben» in der Antike und im frühen Christentum</em> (1939); B. 641, 740; EDNT; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-heos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦héōs⟧</span><span class=\"separator\">·</span><span>conjunção e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἕως</span>. Homero e posteriores.</p><p class=\"entry-text\">① <strong>Indica o termo final de determinado intervalo: até; até que.</strong></p><p class=\"entry-text\">ⓐ <strong>Como conjunção temporal.</strong> A fonte também emprega <span class=\"greek\">ἕ</span>. como abreviatura de <span class=\"greek\">ἕως</span>.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Com indicativo aoristo</strong> (Lísias 25, 26; Ps.-Demóstenes 47, 58; Wsd 10:14; 1Mc 10:50; Jdt 10:18; En 13:7; 102:10; PsSol 2:26; 4:10; SibOr 5, 528; Ar. 12, 2): <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐστάθη</span>, «até que parou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>; <span class=\"greek\">ἕως</span> <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κατακλυσμός</span>, «até que veio o dilúvio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:10</a>, códice D.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Com subjuntivo aoristo e normalmente <span class=\"greek\">ἄν</span></strong>, como requer a regra sintática (A. Fuchs, <em>Die Temporalsätze mit dem Konjunktiv «bis» und «so lange als»</em> [1902]; Xenofonte, An. 5, 1, 11; SIG 966, 11; 1207, 10; PPetr II, 40a, 28; POxy 1124, 7; Gn 24:14; 49:10; Êx 33:22; Lv 22:4; LXX frequentemente; TestAbr B 7, p. 112, 2 [Stone p. 72]; TestJob 21:2; ParJer 2:3; ApcMos 26, p. 14, 7 Tdf.; Josefo, Ant. 13, 400; Justino, A I, 45, 1). Denota um acontecimento cujo início depende de determinadas condições: <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">εἴπω</span> <span class=\"greek\">σοι</span>, «até que eu te diga», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:13</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a> (A. Honeyman, NTS 1 [1954/55], 141s.), 26 (SIG 731, 16ss. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἀποδῷ</span>); 10:23; 22:44 (Sl 109:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:10</a>; 9:1; 12:36 (Sl 109:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:43</a> (Sl 109:1); 21:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:35</a> (Sl 109:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a>; B 12:10 (as duas últimas citações de Sl 109:1).</p><p class=\"entry-text\"><strong>Sem <span class=\"greek\">ἄν</span></strong> (Sófocles, Aj. 555; Phil. 764; Políbio 35, 2, 4; SIG 976, 79; UPZ 18, 10 [séc. II a.C.]; PGrenf II, 38, 16 [séc. I a.C.]; POxy 531, 6; 1125, 15; 1159, 21; Sir 35:17; Tb 14:5 BA; En 10:12, 17; TestSol 15:10; ParJer 5:14; GrBar 11:2; SibOr 5, 217; Justino, D. 39, 6): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:23</a>, variante; 18:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:4</a> e 22:34 (ambos com variante <span class=\"greek\">ἕως</span> <span class=\"greek\">οὗ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:11</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Com indicativo presente</strong> (cf. Plutarco, Lycurg. 29, 3): <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔρχομαι</span>, «até que eu venha», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:22</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4:13</a>; Hs 5, 2, 2; 9, 10, 5s.; cf. 9, 11, 1.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <strong>Com indicativo futuro</strong>, em passagem textualmente duvidosa (PHolm 26, 7; Jdt 10:15; B-D-F §382, 2; Robertson 971s.; 976): <span class=\"greek\">ἕως</span> <span class=\"greek\">ἥξει</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">εἴπητε</span>, «até que venha [o tempo] em que digais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:35</a>; há variante sem <span class=\"greek\">ἥξει</span> <span class=\"greek\">ὅτε</span>.</p><p class=\"entry-text\">ⓑ <strong>Como preposição: até; até o limite de.</strong> Essa função aparece a partir do fim do século IV a.C. (Schwyzer II 550); Aristóteles e posteriores, inscrições, papiros, LXX, pseudepígrafos, SibOr 5, 57, 118.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. No uso preposicional, <span class=\"greek\">ἕ</span>. volta a abreviar <span class=\"greek\">ἕως</span>. <strong>Com genitivo de substantivo ou expressão equivalente</strong> (SIG 588, 64 [196 a.C.] <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">συνθήκης</span> <span class=\"greek\">χρόνου</span>, «até o tempo do acordo»; OGI 90, 16 <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πρώτου</span> <span class=\"greek\">ἔτους</span>, «até o primeiro ano»; BGU 1128, 8 [14 a.C.]; LXX; TestAbr A 20, p. 103, 23 [Stone p. 54]). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, «até o dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:80</a> (cf. Jdt 12:14; 1Esd 4:55; 1Mc 13:39). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἐκείνης</span>, «até aquele dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:25</a> (Jdt 1:15). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ταύτης</span>, «até este dia», 1Cl 11:2 (4Km 17:23; 1Mc 8:10; 13:30; 1Esd 8:73; Bar 1:13; ApcMos 13, p. 7, 1 Tdf.). <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὥρας</span> <span class=\"greek\">ἐνάτης</span>, «até a nona hora», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:44</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πεντηκοστῆς</span>, «até Pentecostes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:8</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σήμερον</span>, com <span class=\"greek\">ἡμέρας</span> implícito, «até hoje», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:8</a> (Justino, D. 134, 5). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τέλους</span>, «até o fim», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:8</a> (JosAs 12:3). <span class=\"greek\">ἕ</span>. <span class=\"greek\">αἰῶνος</span>, «para sempre» (1Cr 17:16; Sir 24:9; 44:13; Jdt 13:19; 1Esd 8:82; PsSol 18:11; TestJob 34:4), Hv 2, 3, 3.</p><p class=\"entry-text\"><strong>Com referência à idade ou duração da vida:</strong> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">ὀγδοήκοντα</span> <span class=\"greek\">τεσσάρων</span>, «até a idade de oitenta e quatro anos», provavelmente «até que ela tinha então oitenta e quatro anos» (Goodspeed, <em>Problems</em>, 79–81), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:37</a> (cf. Josefo, Ant. 5, 181).</p><p class=\"entry-text\"><strong>Com nomes próprios:</strong> <span class=\"greek\">ἕ</span>. <span class=\"greek\">Ἰωάννου</span>, «até o tempo de João», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:13</a> (Políbio 2, 41, 5; Diodoro Sículo 1, 50, 6); <span class=\"greek\">ἕ</span>. <span class=\"greek\">Σαμουήλ</span>, «até Samuel», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:20</a>.</p><p class=\"entry-text\"><strong>Na relação <span class=\"greek\">ἀπό</span> … <span class=\"greek\">ἕως</span>, «desde … até»</strong>, típica em outros contextos (Bar 1:19; 1Esd 8:73; Sir 40:1; 1Mc 16:2; 3Mc 6:38; Demétrio, 722 Fgm. 1, 18 Jac.): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">Δαυίδ</span>, «de Abraão até Davi», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:17</a>a. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βαπτίσματος</span> <span class=\"greek\">Ἰωάννου</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, «desde o batismo de João até o dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:22</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἕκτης</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὥρας</span> <span class=\"greek\">ἐνάτης</span>, «desde a sexta hora até a nona», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:45</a> (SIG 736, 109 [92 a.C.] <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τετάρτας</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἑβδόμας</span>; 1Esd 9:41). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πρωὶ̈</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἑσπέρας</span>, «da manhã à tarde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:23</a> (Josefo, Ant. 6, 364). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span>, «até agora» (Ps.-Luciano, Halc. 4; SIG 705, 44s. [112 a.C.]; UPZ 122 [157 a.C.]; Gn 15:16; 18:12; Nm 14:19; 1Mc 2:33), após <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἀρχῆς</span>, «desde o princípio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:19</a> (BGU 1197, 8 [4 a.C.] <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νῦν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐννεακαιδεκάτου</span> <span class=\"greek\">ἔτους</span> <span class=\"greek\">Καίσαρος</span>; Ez 4:14). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">μετοικεσίας</span> <span class=\"greek\">Βαβυλῶνος</span>, «de Davi ao exílio babilônico», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:17</a>b. Um acontecimento histórico pode ser o limite temporal (1Esd 5:71; ParJer 3:11), como <span class=\"greek\">ἕ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">τελευτῆς</span> <span class=\"greek\">Ἡρῴδου</span>, «até a morte de Herodes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:15</a>.</p><p class=\"entry-text\"><strong>Com infinitivo articular</strong>, sobre o acusativo desse infinitivo ver B-D-F §406, 3: <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐλθεῖν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Καισάρειαν</span>, «até que ele chegasse a Cesareia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:40</a> (SIG 588, 93s.; Gn 24:33; 28:15; 1Mc 3:33; 5:19; Políbio e Josefo, B-D-F §403). Ver também ③ⓐ, adiante.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Com genitivo neutro do pronome relativo (<span class=\"greek\">οὗ</span> ou <span class=\"greek\">ὅτου</span>):</strong></p><p class=\"entry-text\">א. <span class=\"greek\">ἕ</span>. <span class=\"greek\">οὗ</span>, «até que» (Heródoto 2, 143; Plutarco e outros; LXX; En; TestAbr; TestJob 24:4; com valor local SIG 495, 101). <strong>Com aoristo do indicativo</strong> (Jz 3:30; 4:24 B; 4Km 17:20; Tb 1:21; 2:4, 10; Jdt 10:10; 15:5; JosAs 10:2, 19; Josefo, Ant. 10, 134): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:25</a>; 13:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:26</a>. <strong>Com aoristo do subjuntivo</strong> (BGU 1209, 8 [23 a.C.]; PRyl 229, 14 [38 d.C.]; Jz 5:7 B; Sl 71:7; Jdt 6:5, 8; TestAbr B 2, p. 107, 3 [Stone p. 62]; ParJer 9:3; GrBar 13:5; ApcMos 31, p. 17, 10 Tdf.): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:4</a>, variante, 8; 22:18; 24:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:19</a>. <strong>Depois de negação, «até que; antes que»:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:12</a>, 14, 21.</p><p class=\"entry-text\">ב. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὅτου</span>, «até que». <strong>Com aoristo do indicativo</strong> (Diodoro Sículo 19, 108, 3; 3Km 10:7; 11:16; Dn 2:34; 7:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:18</a>. <strong>Com aoristo do subjuntivo</strong> (POxy 1061, 16 [22 a.C.]; 1Km 22:3; 2Esd 14:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:50</a>; 13:8; 15:8, variante; 22:16, 18, variante.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Com advérbio de tempo</strong> (JosAs 10:17 <span class=\"greek\">ἕ</span>. <span class=\"greek\">πρωί̈</span>; Atenágoras 22, 6 <span class=\"greek\">ἕ</span>. <span class=\"greek\">νῦν</span>). <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἄρτι</span>, «até agora» (ver <span class=\"greek\">ἄρτι</span> ③), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:10</a>; 5:17; 16:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:13</a>; 8:7; 15:6. <span class=\"greek\">ἕ</span>. <span class=\"greek\">σήμερον</span>, «até hoje» (Sir 47:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:15</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">πότε</span>;, «até quando?» (Sl 12:2, 3; 2Km 2:26; 1Mc 6:22; ApcSed 12:1s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:17</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:19</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:10</a>.</p><p class=\"entry-text\">② <strong>Designar simultaneidade: enquanto; durante todo o tempo em que.</strong></p><p class=\"entry-text\">ⓐ <strong>Como conjunção com indicativo</strong> (Homero e posteriores; Jdt 5:17), na literatura aqui abrangida somente o presente (Apiano, Bell. Civ. 2, 53 §218 <span class=\"greek\">ἕως</span> <span class=\"greek\">χειμάζουσιν</span>; ibid. <span class=\"greek\">ἕως</span> <span class=\"greek\">Πομπήιος</span> <span class=\"greek\">ἡγεῖται</span>, «enquanto Pompeu supõe»; Josefo, Bell. 7, 347; Justino, D. 4, 4 <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span>, «enquanto a alma está no corpo»): <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἐστίν</span>, «enquanto é dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:4</a> (variante <span class=\"greek\">ὡς</span>; para a alternância, L. Radermacher, Philol. 60 [1901], 495s.; B-D-F §455, 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:35</a>s., variante; <span class=\"greek\">ἕ</span>. <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἀπολύει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὄχλον</span>, «enquanto ele mesmo despedia a multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:45</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὑπάγουσιν</span>, «enquanto estavam a caminho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:10</a>, códice D. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἔχομεν</span>, «enquanto ainda temos», 2Cl 16:1 (cf. Platão, Phd. 89c <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐστιν</span>, «enquanto ainda é dia»; Parmen. 135d <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">νέος</span> <span class=\"greek\">εἶ</span>, «enquanto ainda és jovem»; Apiano, Bell. Civ. 3, 32 §127 <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">δύνασαι</span>, «enquanto ainda podes»; PEleph 14, 24 [223 a.C.]; Sir 33:21 <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζῇς</span>, «enquanto ainda vives»).</p><p class=\"entry-text\">ⓑ <strong>Como conjunção com subjuntivo</strong> (PTebt 6, 42 [140 a.C.] <span class=\"greek\">ἕως</span> … <span class=\"greek\">μένωσι</span>, «enquanto permanecerem»; Dião Crisóstomo 27 [44], 5 <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> … <span class=\"greek\">φέρῃ</span>, «enquanto durar»; Apiano, Numid. 4 §2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:8</a>.</p><p class=\"entry-text\">ⓒ <strong>Como preposição seguida de genitivo neutro do relativo</strong>, em casos especiais, ainda com o sentido «enquanto»: <span class=\"greek\">ἕ</span>. <span class=\"greek\">οὗ</span> (Josefo, Ant. 3, 279, com <span class=\"greek\">ἔχουσι</span>), seguido de subjuntivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:22</a>; 26:36 (mas ver Burton, <em>MT</em> §325; Zwaan §314). <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὅτου</span> (Ct 1:12), seguido de indicativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a>.</p><p class=\"entry-text\">③ <strong>Marca do limite espacial atingido: até; tão longe quanto</strong>, com função de preposição.</p><p class=\"entry-text\">ⓐ <strong>Com genitivo de lugar</strong> (Políbio 3, 76, 2; Diodoro Sículo 1, 27, 5; SIG 588, 32 [196 a.C.] <span class=\"greek\">ἕ</span>. <span class=\"greek\">θαλάσσης</span>, «até o mar»; 1231, 12 <span class=\"greek\">ἀπὸ</span> … <span class=\"greek\">ἕως</span>; PTebt 33, 5 [112 a.C.]; LXX; En 21:1; 22:6; PsSol 15:10; TestAbr A 5, p. 82, 12s. [Stone p. 12]; TestJob 20:6; GrBar 2:5; 11:8; JosAs 16:14; Josefo, Bell. 1, 512; Melitão, HE 4, 26, 14 <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> … , <span class=\"greek\">ἔνθα</span>, «até o lugar onde»). <span class=\"greek\">ἕ</span>. <span class=\"greek\">Φοινίκης</span>, «até a Fenícia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:19</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">Ἀντιοχείας</span>, «até Antioquia», v. 22. <span class=\"greek\">ἕ</span>. <span class=\"greek\">Βηθλεέμ</span>, «até Belém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:15</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">οὐρανοῦ</span>, <span class=\"greek\">ᾅδου</span>, «até o céu; até o Hades», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:15</a> (ApcEsdr 4:32, p. 29, 8 Tdf.). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αὐλῆς</span>, «até o pátio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:58</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:29</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span>, «até os confins da terra» (Is 48:20; 62:11; 1Mc 3:9; PsSol 1:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:8</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">τρίτου</span> <span class=\"greek\">οὐρανοῦ</span>, «até o terceiro céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:2</a> (ApcSed 2:4).</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">ἀπὸ</span> … <span class=\"greek\">ἕως</span>, «de … até»:</strong> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνατολῶν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">δυσμῶν</span>, «do oriente ao ocidente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:27</a>. <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄκρων</span> <span class=\"greek\">οὐρανῶν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἄκρων</span> <span class=\"greek\">αὐτῶν</span>, «das extremidades dos céus até as outras extremidades», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a> (cf. Dt 30:4). <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄκρου</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἄκρου</span> <span class=\"greek\">οὐρανοῦ</span>, «de uma extremidade da terra à extremidade do céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:27</a> (Jdt 11:21). <strong>Com genitivo de pessoa localizada em certo lugar</strong> (Eliano, VH 3, 18 <span class=\"greek\">ἕ</span>. <span class=\"greek\">Ὑπερβορέων</span>, «até os hiperbóreos»; 4Km 4:22; 1Mc 3:26): <span class=\"greek\">ἦλθον</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">αὐτοῦ</span>, «chegaram até ele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:42</a>; <span class=\"greek\">διελθεῖν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἡμῶν</span>, «ir até nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:38</a>. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:40</a> também se enquadra aqui (ver ①ⓑ<span class=\"greek\">α</span>), comparável a Gn 10:19.</p><p class=\"entry-text\">ⓑ <strong>Com advérbio espacial</strong> (LXX): <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἄνω</span>, «até em cima; até a borda» (2Cr 26:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:7</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἔσω</span>, «até o interior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:54</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">κάτω</span>, «até embaixo» (Ez 1:27; 8:2, em relação a <span class=\"greek\">ἀπό</span>); <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">κάτω</span>, «de cima a baixo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:38</a> (cf. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἔσω</span> <span class=\"greek\">ἕω</span> <span class=\"greek\">ἔξω</span>, TestSol 18:15 P). <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὧδε</span>, «até aqui» (Gn 22:5; 2Km 20:16; 3Km 18:45; Ar. 17, 1); <span class=\"greek\">ἀρξάμενος</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ὧδε</span>, «começando da Galileia até aqui», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:5</a>.</p><p class=\"entry-text\">ⓒ <strong>Com outra preposição ou advérbio:</strong> <span class=\"greek\">ἕ</span>. <span class=\"greek\">πρός</span> (Políbio 3, 82, 6; 12, 17, 4; Gn 38:1; Ez 48:1); <span class=\"greek\">ἕ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">Βηθανίαν</span>, «até as proximidades de Betânia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:50</a> (variante <span class=\"greek\">ἕ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">Β</span>., cf. Políbio 1, 11, 14; Diodoro Sículo 1, 27, 5; Eliano, VH 12, 22; Dt 31:24; 4Km 2:6; PsSol 2:5; Josefo, Ant. 16, 90). <span class=\"greek\">ἕ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span>, «até mesmo em», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:11</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, «até fora da cidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:5</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, «até o mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:14</a> (cf. 1Mc 5:29; 3Mc 7:18 A; PsSol 17:12; <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολύ</span>, «até muito longe», TestSol 7:2).</p><p class=\"entry-text\">④ <strong>Indica a posição final numa série: até.</strong> <span class=\"greek\">ἀρξάμενος</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐσχάτων</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">πρώτων</span>, «começando dos últimos até os primeiros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">δεύτερος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τρίτος</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑπτά</span>, «o segundo, o terceiro, até o sétimo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:26</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μικροῦ</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">μεγάλου</span>, «do menor ao maior» (Bar 1:4; 1Mc 5:45; Jdt 13:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:11</a> (Jr 38:34); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:9</a>, variante.</p><p class=\"entry-text\">⑤ <strong>Indica o limite máximo de grau ou medida: até; ao ponto de; tanto quanto.</strong> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἑπτάκις</span>, «até sete vezes» (4Km 4:35; cf. TestSol 5:8 <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἑπτά</span>; ApcSed 16:4 <span class=\"greek\">ἕ</span>. <span class=\"greek\">εἴκοσι</span>, «até vinte»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:21</a>s.; cf. v. 22. <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἡμίσους</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">μου</span>, «até metade do meu reino» (Est 5:3; 7:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:23</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἑνός</span>, «não há sequer um» (PTebt 56, 7 [séc. II a.C.] <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">τροφῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κτηνῶν</span> <span class=\"greek\">ἡμῶν</span>, «não temos nem mesmo alimento para nossos animais»; Leôncio, <em>Vita Johannis</em> [H. Gelzer, 1893], 66, 21ss. <span class=\"greek\">οὐ</span> … <span class=\"greek\">ἕως</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">νομίσματος</span>, «nem sequer uma moeda»; PRossGeorg III, 3, 22 <span class=\"greek\">ἕως</span> <span class=\"greek\">δραχμῶν</span> <span class=\"greek\">ἕκατον</span>, «até cem dracmas»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:12</a> (Sl 13:3). <span class=\"greek\">ἐᾶτε</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">τούτου</span>, «basta!; não mais!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:51</a> (<span class=\"greek\">ἕ</span>. <span class=\"greek\">τούτου</span>, «até este ponto», Aristóteles, HA 9, 46; Políbio 9, 36, 1; 2Km 7:18). <span class=\"greek\">ἕ</span>. <span class=\"greek\">θανάτου</span>, «até a morte» (Antígono de Caristo 16; Sir 34:12; 51:6; 4Mc 14:19; JosAs 29:3): <strong>lutar até a morte</strong>, 1Cl 5:2 (Sir 4:28; cf. OGI 266, 29 [séc. III a.C.] <span class=\"greek\">μαχοῦμαι</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θανάτου</span>, «lutarei pela vida e até a morte»). <span class=\"greek\">περίλυπός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">θανάτου</span>, «minha alma está profundamente triste até a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:34</a> (cf. Jn 4:9 <span class=\"greek\">σφόδρα</span> <span class=\"greek\">λελύπημαι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">θανάτου</span>, «estou extremamente triste, até a morte»).</p><p class=\"entry-text\"><strong>Bibliografia:</strong> DELG, s.v. <span class=\"greek\">ἕω</span> ②; EDNT; <em>New Docs</em> 4, 154; M-M.</p></section></article>\n<article id=\"entry-heosphoros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑωσφόρος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heōsphóros⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑωσφόρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>. De <span class=\"greek\">ἕω</span>, forma ática do jônico <span class=\"greek\">ἠώ</span>, «aurora; manhã», e <span class=\"greek\">φέρω</span>, «trazer». Homero, Hesíodo e posteriores; LXX; Fílon. <strong>Estrela da manhã</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:19</a>, variante textual. Bibliografia: DELG, s.v. <span class=\"greek\">ἕω</span> ①. O sinal <span class=\"greek\">Ϛ</span> na sequência da fonte é o início do verbete autônomo seguinte, não parte da acepção.</p></section></article>\n<article id=\"entry-stigma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ϛ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦stígma; vaû⟧</span><span class=\"separator\">·</span><span>letra e numeral grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ϛ</span>. <strong>Estigma ou vau</strong>, cf. o semítico <em>waw</em>, ו. Sexta letra dos alfabetos gregos mais antigos. Utilizada para designar o <strong>numeral 6</strong>, sob a forma <span class=\"greek\">Ϛ</span>´; uma forma anterior é <span class=\"greek\">ϝ</span> (ver Schwyzer III 110, índice; L-S-J-M, s.v. F). Indica «seis» ou «sexto» nos títulos de Hm 6 e Hs 6. Comparar a entrada <span class=\"greek\">χξϚ</span>´, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:18</a>, variante de leitura. A letra <span class=\"greek\">Ζ</span> que aparece ao fim do fragmento corresponde à passagem à seção alfabética seguinte, não a uma acepção de <span class=\"greek\">Ϛ</span>.</p></section></article>\n"};
